css:
/* ============ VIRIDIAN · Marquee — global row ============
   Prepended to the parent theme's base.css, which makes this file the owner of the sheet's only
   @import — a second one further down is invalid and dropped, so the inherited font families are
   repeated below. Prepended also means a plain :root loses on source order: every override here
   needs :root:root, or the theme silently stays the parent's colour. */
@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Inter:wght@400;500;600;700;800&family=Oxanium:wght@500;600;700;800&family=IBM+Plex+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;700&display=swap');

:root{
  --mq-poster:'Bebas Neue','Oxanium',sans-serif;   /* condensed marquee caps */
  --mq-ui:'Inter','IBM Plex Sans',system-ui,sans-serif;
  --mq-mono:'JetBrains Mono',Consolas,monospace;
  --mq-r:20px;        /* fatter corner than the inherited chrome — a softer, poster-ish frame */
  --mq-r-sm:12px;
  --mq-ink:var(--mud-palette-text-primary);
}

/* ---- The recolour: jade over the inherited ember ----
   The whole re-skin is this one block — the parent routes every warm value through its recolour
   contract, so nothing else here paints. Hue is not a state signal: cooling still runs on the one
   inherited --tca-cool lever (jade → ash), and --tca-ash is nudged green-grey so a stopped service
   reads as the same metal, drained. */
:root:root{
  /* jade ramp, light -> deep */
  --mlt-ember-hi:#c8f7e4;          /* seam highlight (pale mint) */
  --mlt-ember-1:#4ce0ad;
  --mlt-ember-mid:#12cf95;         /* seam mid stop */
  --mlt-ember-2:#00c48a;           /* CORE — VIRIDIAN's one identity colour */
  --mlt-ember-3:#00916b;
  --mlt-ember-rgb:0,196,138;       /* = ember-2 */
  --mlt-ember-hot-rgb:0,214,150;   /* the big corner radials run brighter */
  --mlt-ember-shade-rgb:0,60,42;   /* inset shadow under raised jade surfaces */
  --mlt-counter-rgb:217,138,75;    /* counter-glow is copper here — the one warm note left */
  --mlt-ink-on-ember:#04140f;      /* near-black green ink on the jade gradient */
  --mlt-ink-bright:#eef5f2;        /* cool off-white on the dark backdrop (login hero) */
  --mlt-backdrop:linear-gradient(160deg,#0e1614 0%,#0a0f0d 55%,#060b09 100%);
  --tca-ash:#5a6b66;               /* dead metal, green-grey to match the jade ramp */

  /* Poster voice for the wordmark (Bebas ships ONE weight — 800 gets synthetic bold) */
  --mlt-font-brand:var(--mq-poster);
  --mlt-brand-weight:400;
}

/* Brand text comes from Branding.Title/Subtitle, so topbar, drawer, footer, seam-tag and profile
   rows all stay inherited. Two things a token can't carry, patched here instead:
     - the ingot GLYPH — the inherited rows hardcode a flame, and Font Awesome renders through
       ::before{content}, so overriding that alone swaps one character (\f005 = fa-star) and keeps
       FA's own font-family and weight;
     - the lockup SIZE — Bebas is narrower and shorter-x-height than Oxanium at the same px. */
.mlt-ingot i::before{content:"\f005"}
.mlt-dh .mlt-dh__word{font-size:1.42rem;letter-spacing:.14em}
.mlt-tbs .mlt-tbs__word{font-size:1.16rem;letter-spacing:.15em}
.mlt-dh .mlt-dh__tag{font-size:.58rem;letter-spacing:.16em}

/* Login poster moments already follow --mlt-font-brand; only the weight needs correcting, since
   they ask for 700 and Bebas has one. UI type stays Oxanium — tabs, dialog titles and stat
   numbers are not poster moments. */
.mlt-login .mlt-login__headline{font-weight:400;letter-spacing:.02em;line-height:.92}
.mlt-login .mlt-login__panel-head h2{font-weight:400;letter-spacing:.03em}

/* Registering the bridge's numbers makes gauges tween between 1s ticks instead of stepping.
   Registered also means always defined, so var(--svc-cpu, 0) can't tell "no data" from zero —
   the markup gates on Permissions.* at render time instead, and never asks. --tca-cool is
   re-listed here because base.css declares its own :root transition further down the sheet. */
@property --svc-cpu{syntax:'<number>';inherits:true;initial-value:0}
@property --svc-memory{syntax:'<number>';inherits:true;initial-value:0}
@property --svc-disk{syntax:'<number>';inherits:true;initial-value:0}
@property --svc-players{syntax:'<number>';inherits:true;initial-value:0}
:root:root{transition:--tca-cool 1s ease,
  --svc-cpu .9s ease,--svc-memory .9s ease,--svc-disk .9s ease,--svc-players .9s ease}

@media (prefers-reduced-motion:reduce){ :root:root{transition:none} }

/* ---- inherited from the parent theme ---- */
@import url('https://fonts.googleapis.com/css2?family=Oxanium:wght@500;600;700;800&family=IBM+Plex+Sans:ital,wght@0,400;0,500;0,600;0,700;1,400&family=JetBrains+Mono:wght@400;500;700&display=swap');
:root{
  --mlt-font-display:'Oxanium','Segoe UI',system-ui,sans-serif;
  --mlt-font-body:'IBM Plex Sans','Segoe UI',system-ui,sans-serif;
  --mlt-font-mono:'JetBrains Mono',Consolas,monospace;
  --mlt-font-brand:var(--mlt-font-display);
  --mlt-brand-weight:800;
  --mlt-ember-hi:#ffd9a1;          
  --mlt-ember-1:#ffb347;
  --mlt-ember-mid:#ff9d2e;         
  --mlt-ember-2:#ff7a2e;           
  --mlt-ember-3:#ff4d24;
  --mlt-ember-rgb:255,122,46;      
  --mlt-ember-hot-rgb:255,102,26;  
  --mlt-ember-shade-rgb:120,30,0;  
  --mlt-counter-rgb:90,169,230;    
  --mlt-ink-on-ember:#221004;      
  --mlt-ink-bright:#f3eee8;        
  --mlt-backdrop:linear-gradient(160deg,#101318 0%,#0b0d11 55%,#0d0a08 100%);
  --mlt-radius:14px;
  --mlt-seam-h:linear-gradient(90deg,transparent,var(--mlt-ember-mid) 18%,var(--mlt-ember-hi) 50%,var(--mlt-ember-2) 82%,transparent);
  --mlt-seam-v:linear-gradient(180deg,var(--mlt-ember-1),var(--mlt-ember-2) 55%,var(--mlt-ember-3));
  --mlt-molten:linear-gradient(135deg,var(--mlt-ember-1) 0%,var(--mlt-ember-2) 48%,var(--mlt-ember-3) 100%);
}
@property --tca-cool{syntax:'<number>';inherits:true;initial-value:0}
:root{
  --tca-ash:#5b6472;                      
  --tca-cool:0;
  --tca-ember-now:color-mix(in srgb, var(--tca-ash) calc(var(--tca-cool) * 100%), var(--mlt-ember-2));
  --tca-glow-now:calc(1 - var(--tca-cool) * .75);
  transition:--tca-cool 1s ease;
}
html[data-tca-status="stopped"]{--tca-cool:1}
html[data-tca-status="starting"],
html[data-tca-status="stopping"]{--tca-cool:.5}
[data-tca-component="service-details"]{background:transparent!important;border:1px solid var(--mud-palette-lines-default);
  border-radius:var(--mlt-radius);overflow:hidden;height:auto}
[data-tca-component="service-details"] [data-part="icon"]{display:none}     
[data-tca-component="service-details"] [data-part="row"] td{
  border-bottom:1px solid rgba(var(--mud-palette-text-primary-rgb),.06);padding:9px 16px;vertical-align:middle}
[data-tca-component="service-details"] [data-part="row"]:last-child td{border-bottom:none}
[data-tca-component="service-details"] [data-part="row"] td:first-child{width:196px;
  background:rgba(var(--mud-palette-text-primary-rgb),.02)}
[data-tca-component="service-details"] [data-part="label"]{font-family:var(--mlt-font-mono);
  font-size:.6rem;letter-spacing:.17em;text-transform:uppercase;opacity:.5}
[data-tca-component="service-details"] [data-part="value"]{font-family:var(--mlt-font-display);
  font-weight:600;font-size:.95rem;letter-spacing:.01em}
[data-tca-component="service-details"] [data-part="media"]{border-radius:6px;
  box-shadow:0 2px 8px rgba(0,0,0,.3)}
@media (max-width:599.98px){
  [data-tca-component="service-details"] [data-part="row"],
  [data-tca-component="service-details"] [data-part="row"] td{display:block}
  [data-tca-component="service-details"] [data-part="row"]{
    border-bottom:1px solid rgba(var(--mud-palette-text-primary-rgb),.06)}
  [data-tca-component="service-details"] [data-part="row"]:last-child{border-bottom:none}
  [data-tca-component="service-details"] [data-part="row"] td{border-bottom:none;padding:0 14px}
  [data-tca-component="service-details"] [data-part="row"] td:first-child{
    width:auto;background:transparent;padding-top:9px}
  [data-tca-component="service-details"] [data-part="row"] td:last-child{padding-bottom:10px}
  [data-tca-component="service-details"] [data-part="row"] td:last-child [data-part="value"]{
    display:flex;flex-wrap:wrap;gap:7px;align-items:center}
}
[data-tca-component="service-advanced-actions"]{background:transparent!important}
[data-tca-component="service-advanced-actions"] [data-part="list"]{display:grid;
  grid-template-columns:repeat(auto-fill,minmax(216px,1fr));gap:10px}
[data-tca-component="service-advanced-actions"] [data-part="item"]{display:block}
[data-tca-component="service-advanced-actions"] [data-part="item"] td{display:block;padding:0;border:none}
[data-tca-component="service-advanced-actions"] [data-part="action"]{width:100%;height:46px;
  justify-content:flex-start;gap:10px;padding:0 15px;border-radius:11px;
  border:1px solid var(--mud-palette-lines-default);
  background:linear-gradient(180deg, rgba(255,255,255,.03), transparent 60%), rgba(var(--mud-palette-surface-rgb),.7);
  font-family:var(--mlt-font-display);font-size:.76rem;font-weight:600;letter-spacing:.09em;
  text-transform:uppercase;color:var(--mud-palette-text-primary);
  transition:border-color .15s, background .15s, transform .1s}
[data-tca-component="service-advanced-actions"] [data-part="item"]:hover [data-part="action"]{transform:translateY(-1px);
  background:color-mix(in srgb, currentColor 10%, transparent)}
[data-tca-component="service-advanced-actions"] [data-part="action"]:active{transform:translateY(0)}
[data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="settings"]{
  border-color:color-mix(in srgb, var(--mlt-ember-2) 45%, transparent);color:var(--mlt-ember-1)}
[data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="reinstall"],
[data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="repair"]{
  border-color:color-mix(in srgb, var(--mud-palette-warning) 45%, transparent);color:var(--mud-palette-warning)}
[data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="delete"]{
  border-color:color-mix(in srgb, var(--mud-palette-error) 55%, transparent);color:var(--mud-palette-error);
  background:linear-gradient(180deg, color-mix(in srgb, var(--mud-palette-error) 9%, transparent), transparent 70%)}
[data-tca-component="service-advanced-actions"] [data-part="item"]:hover [data-part="action"][data-kind="delete"]{
  background:color-mix(in srgb, var(--mud-palette-error) 16%, transparent)}
[data-tca-component="docker-ports"] [data-part="value"][data-kind="address"]{
  display:inline-flex;align-items:center;gap:10px;font-family:var(--mlt-font-mono);
  font-size:.92rem;letter-spacing:.06em}
[data-tca-component="docker-ports"] [data-part="value"][data-kind="address"]::before{content:"NODE";
  font-size:.55rem;letter-spacing:.2em;opacity:.5;padding:3px 7px;border-radius:5px;
  border:1px solid var(--mud-palette-lines-default)}
[data-tca-component="docker-ports"] [data-part="item"][data-kind="port"],
[data-tca-component="service-details"] [data-part="item"][data-kind="port"]{
  font-family:var(--mlt-font-mono)!important;font-size:.7rem;letter-spacing:.05em;border-radius:7px;
  border:1px solid color-mix(in srgb, var(--tca-ember-now) 45%, transparent)!important;
  background:color-mix(in srgb, var(--tca-ember-now) 10%, transparent)!important;
  color:var(--mud-palette-text-primary)!important}
[data-tca-component="docker-ports"] [data-part="item"][data-kind="more"]{
  font-family:var(--mlt-font-mono);font-size:.68rem;opacity:.55}
body,.mud-typography,.mud-input,.mud-input *,.mud-select,.mud-menu-list,.mud-list,
.mud-table,.mud-button-root:not(.mud-fab),.mud-chip,.mud-tooltip,.mud-alert,.mud-breadcrumbs{
  font-family:var(--mlt-font-body);
}
.mud-typography-h1,.mud-typography-h2,.mud-typography-h3,.mud-typography-h4,
.mud-typography-h5,.mud-typography-h6,.mud-dialog-title,.mud-card-header .mud-typography{
  font-family:var(--mlt-font-display);
  letter-spacing:.015em;
}
code,kbd,pre,.mud-code,.xterm{font-family:var(--mlt-font-mono)}
.mlt-seam{height:2px;border-radius:2px;background:var(--mlt-seam-h);background-size:220% 100%;
  animation:mlt-flow 9s linear infinite;opacity:.9}
.mlt-mono{font-family:var(--mlt-font-mono);letter-spacing:.14em;text-transform:uppercase}
.mlt-bc ~ .mud-container{margin-top:4px!important;padding-top:0!important}
.mlt-ft__link .mud-tooltip-root,.mlt-tbe__pill .mud-tooltip-root{display:flex;align-items:center;line-height:0}
.mlt-svh__chip .tca-service-icon{display:flex;align-items:center;justify-content:center;line-height:0}
.mlt-ingot{display:inline-flex;align-items:center;justify-content:center;flex:none;
  width:34px;height:34px;border-radius:9px;color:var(--mlt-ink-on-ember);font-size:16px;
  background:var(--mlt-molten);
  box-shadow:0 3px 12px rgba(var(--mlt-ember-rgb),.45),inset 0 1px 0 rgba(255,255,255,.5),inset 0 -2px 4px rgba(var(--mlt-ember-shade-rgb),.35)}
.mlt-ingot--lg{width:42px;height:42px;border-radius:11px;font-size:20px}
*::-webkit-scrollbar{width:10px;height:10px}
*::-webkit-scrollbar-track{background:transparent}
*::-webkit-scrollbar-thumb{background:rgba(var(--mud-palette-text-primary-rgb),.14);border-radius:8px;
  border:2px solid transparent;background-clip:content-box}
*::-webkit-scrollbar-thumb:hover{background:rgba(var(--mud-palette-primary-rgb),.45);border:2px solid transparent;background-clip:content-box}
@keyframes mlt-flow{0%{background-position:0% 0}100%{background-position:220% 0}}
@keyframes mlt-rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
@keyframes mlt-glow{0%,100%{box-shadow:0 0 22px rgba(var(--mlt-ember-rgb),.35)}50%{box-shadow:0 0 34px rgba(var(--mlt-ember-rgb),.6)}}
@media (prefers-reduced-motion: reduce){
  .mlt-seam,.mlt-svh__seam,.mlt-login__brand::after,.mlx__orb,
  .mlt-login__brand-inner,.mlt-login__card{animation:none!important}
  :root{transition:none}
}

contents.css:
.mud-container:has(> .mlt-svh){margin-top:4px!important;padding-top:0!important}
.mlt-svh{display:flex;align-items:center;gap:18px;flex-wrap:wrap;padding:0 2px}
.mlt-svh__lockup{display:flex;align-items:center;gap:14px;flex:1 1 300px;min-width:0}
.mlt-svh__chip{
  width:46px;height:46px;flex:none;display:flex;align-items:center;justify-content:center;
  border-radius:12px;
  border:1px solid color-mix(in srgb, var(--tca-ember-now) 32%, transparent);
  color:var(--tca-ember-now);
  background:linear-gradient(160deg, color-mix(in srgb, var(--tca-ember-now) 14%, transparent),
                                     color-mix(in srgb, var(--tca-ember-now) 4%, transparent));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.08);
}
.mlt-svh__stack{display:flex;flex-direction:column;gap:2px;min-width:0}
.mlt-svh__name .tca-live-name{
  font-family:var(--mlt-font-display);font-weight:700;font-size:clamp(1.35rem,2.1vw,1.8rem);
  line-height:1.1;letter-spacing:.015em;display:block;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
}
.mlt-svh__ident{font-size:.64rem;opacity:.55;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mlt-svh__conns{gap:10px;align-items:stretch;min-width:0}
.mlt-svh__conncard{
  display:flex;flex-direction:column;gap:3px;justify-content:center;
  padding:7px 12px;border-radius:10px;min-width:0;
  border:1px solid var(--mud-palette-lines-default);
  background:rgba(var(--mud-palette-surface-rgb),.55);
}
.mlt-svh__connlabel{font-size:.55rem;opacity:.5}
.tca-conn{font-family:var(--mlt-font-mono);font-size:.74rem;display:inline-flex;align-items:center;
  gap:2px;white-space:nowrap}
.tca-conn .mud-icon-button{padding:2px;margin-left:2px}
.mlt-svh__power{display:flex;align-items:center;gap:10px;margin-left:auto;flex-wrap:wrap}
.tca-power{
  display:inline-flex;align-items:center;gap:9px;height:40px;padding:0 18px;border-radius:11px;
  font-family:var(--mlt-font-display);font-weight:700;letter-spacing:.06em;text-transform:uppercase;
  font-size:.78rem;border:1px solid transparent;cursor:pointer;background:transparent;color:inherit;
  transition:filter .15s, box-shadow .15s, transform .12s, background .15s;
}
.tca-power:active{transform:translateY(1px)}
.tca-power:disabled{opacity:.45;cursor:default}
.tca-power__icon{font-size:.72rem}
.tca-power-start{
  background:var(--mlt-molten);color:var(--mlt-ink-on-ember);
  box-shadow:0 4px 16px rgba(var(--mlt-ember-rgb),.32), inset 0 1px 0 rgba(255,255,255,.38);
}
.tca-power-start:hover:not(:disabled){filter:brightness(1.07);box-shadow:0 6px 22px rgba(var(--mlt-ember-rgb),.5)}
.tca-power-restart{border-color:color-mix(in srgb, var(--mud-palette-warning) 55%, transparent);color:var(--mud-palette-warning)}
.tca-power-restart:hover:not(:disabled){background:color-mix(in srgb, var(--mud-palette-warning) 12%, transparent)}
.tca-power-stop{border-color:color-mix(in srgb, var(--mud-palette-error) 55%, transparent);color:var(--mud-palette-error)}
.tca-power-stop:hover:not(:disabled){background:color-mix(in srgb, var(--mud-palette-error) 12%, transparent)}
.tca-power-kill{background:var(--mud-palette-error);color:#fff;box-shadow:0 4px 14px color-mix(in srgb, var(--mud-palette-error) 45%, transparent)}
.tca-power-kill:hover:not(:disabled){filter:brightness(1.08)}
.mlt-svh__seam{height:2px;border-radius:2px;margin:12px 2px 18px;
  opacity:calc(.85 * var(--tca-glow-now));
  background:linear-gradient(90deg,transparent,var(--tca-ember-now) 18%,
             color-mix(in srgb, var(--tca-ember-now) 45%, #fff) 50%, var(--tca-ember-now) 82%,transparent);
  background-size:220% 100%;animation:mlt-flow 30s linear infinite}
@media (max-width:959.98px){
  .mlt-svh{gap:12px;flex-wrap:nowrap}
  .mlt-svh__lockup{flex:1 1 auto;gap:10px}
  .mlt-svh__power{margin-left:auto;width:auto;flex:none;flex-wrap:nowrap;gap:8px}
  .tca-power{height:36px;padding:0 14px;font-size:.72rem}
  .mlt-svh__chip{width:40px;height:40px;border-radius:10px}
  .mlt-svh__seam{margin:10px 2px 12px}
}
@media (max-width:599.98px){
  .tca-power__label{display:none}
  .tca-power{padding:0 12px;gap:0}
  .tca-power__icon{font-size:.85rem}
}

contents.content:
{% comment %} VIRIDIAN · DockerService.Home surface — the game surface's poster hero + workbench
re-cut for a container: no players/slots, no network line, image:tag in the kick line, and two
docker terminals in place of the game console (logs = "Console", exec = "Terminal"). It reuses the
game surface's class names, which is safe because the two never share a page and it keeps the CSS
diffable. {% endcomment %}

{% comment %} First port that carries a click-to-connect URI (phpMyAdmin/nginx-style web UIs).
Plain-Liquid loop rather than map|compact so it can't depend on filter availability. {% endcomment %}
{% comment %} Liquid trap: '' is TRUTHY (only nil/false are falsy), so every test below compares
against '' explicitly — a bare {% if joinUri %} on a portless container rendered a launch button
with a dangling colon. {% endcomment %}
{% assign joinUri = '' %}
{% assign joinPort = '' %}
{% for p in Service.Ports %}{% if p.Uri and p.Uri != '' and joinUri == '' %}{% assign joinUri = p.Uri %}{% assign joinPort = p.Port %}{% endif %}{% endfor %}

<div class="mq mq--dkr">
  <!-- ============================ the marquee ============================ -->
  <section class="mq-hero">
    <div class="mq-hero__body">
      <p class="mq-kick">
        <span>{{ Service.BlueprintName }}</span>
        {% if Service.Image %}<i></i><span>{{ Service.Image }}{% if Service.Tag %}:{{ Service.Tag }}{% endif %}</span>{% endif %}
        <i></i><span>{{ Service.HostnameOrIp }}</span>
      </p>

      <div class="mq-head">
        <h1 class="mq-name">{% component "live-name" %}</h1>
        <p class="mq-state">
          {% component "live-status-orb" %}
          <b>{% component "live-status" %}</b>
          <span class="mq-state__u">for {% component "live-uptime" %}</span>
        </p>
      </div>

      <div class="mq-cta">
        {% comment %} CTA precedence: blueprint Connect URL → first port with a URI → copyable host.
        Started-only clickability is CSS off data-tca-status (live); Liquid here is only a
        render-time snapshot. {% endcomment %}
        {% if Service.ConnectUrl and Service.ConnectUrl != '' %}
        <a class="mq-join" href="{{ Service.ConnectUrl }}" target="_blank" rel="noopener">
          <i class="fa-solid fa-plug"></i><span>{% t 'ServiceHome.Connect', 'Connect' %}</span><em>{{ Service.HostnameOrIp }}</em>
        </a>
        {% elsif joinUri != '' %}
        <a class="mq-join" href="{{ joinUri }}" target="_blank" rel="noopener">
          <i class="fa-solid fa-arrow-up-right-from-square"></i><span>{% t 'Messages.Open', 'Open' %}</span><em>{{ Service.HostnameOrIp }}:{{ joinPort }}</em>
        </a>
        {% else %}
        {% comment %} No launch URI — offer the host to copy. service-host-address is the both-family
        atom; the game-* address atoms render nothing on docker. {% endcomment %}
        <div class="mq-join mq-join--static">
          <i class="fa-solid fa-plug"></i><span>{% t 'Db.Host', 'Host' %}</span><em>{% component "service-host-address" %}</em>
        </div>
        {% endif %}
        {% if Permissions.Control %}
        <div class="mq-keys">
          {% component "power-start" %}
          {% component "power-restart" %}
          {% component "power-stop" %}
          {% component "power-kill" %}
        </div>
        {% endif %}
      </div>

    </div>

    {% if Permissions.LiveStats %}
    <aside class="mq-vitals">
      <div class="mq-tubes">
      {% if Permissions.CpuStats %}
      <div class="mq-vital mq-vital--cpu">
        <span class="mq-tube"><i></i></span>
        <span class="mq-vital__n">{% component "live-cpu" %}</span>
        <span class="mq-vital__k">{% t 'ServiceHome.CPU', 'CPU' %}</span>
      </div>
      {% endif %}
      {% if Permissions.MemoryStats %}
      <div class="mq-vital mq-vital--mem">
        <span class="mq-tube"><i></i></span>
        <span class="mq-vital__n">{% component "live-memory" %}</span>
        <span class="mq-vital__d">of {% component "live-memory-limit" %}</span>
        <span class="mq-vital__k">{% t 'Global.Memory', 'Memory' %}</span>
      </div>
      {% endif %}
      <div class="mq-vital mq-vital--disk">
        <span class="mq-tube"><i></i></span>
        <span class="mq-vital__n">{% component "live-disk" %}</span>
        {% comment %} A disk quota is optional: no quota, no denominator and no --svc-disk sweep. {% endcomment %}
        {% if Service.DiskSpace %}<span class="mq-vital__d">of {% component "live-disk-limit" %}</span>{% endif %}
        <span class="mq-vital__k">{% t 'ServiceHome.Disk', 'DISK' %}</span>
      </div>
      </div>
    </aside>
    {% endif %}
  </section>

  <!-- ============================ the workbench ============================ -->
  <section class="mq-work">
    {% comment %} Which tab opens is a load-time decision, so it belongs in Liquid: running means
    you came for its output, stopped means you came to fix or read. LogConsole is the docker
    read-only log terminal's own permission. {% endcomment %}
    {% assign consoleFirst = false %}
    {% if Permissions.LogConsole and Service.Status == 'Started' %}{% assign consoleFirst = true %}{% endif %}
    {% if Permissions.LogConsole %}<input class="mq-tin" type="radio" name="mq-t" id="mq-t-console"{% if consoleFirst %} checked{% endif %}>{% endif %}
    <input class="mq-tin" type="radio" name="mq-t" id="mq-t-overview"{% unless consoleFirst %} checked{% endunless %}>
    {% if Permissions.Console %}<input class="mq-tin" type="radio" name="mq-t" id="mq-t-exec">{% endif %}
    <input class="mq-tin" type="radio" name="mq-t" id="mq-t-connect">
    {% if Permissions.Logs %}<input class="mq-tin" type="radio" name="mq-t" id="mq-t-logs">{% endif %}
    {% if Permissions.ServiceActivity %}<input class="mq-tin" type="radio" name="mq-t" id="mq-t-activity">{% endif %}
    <input class="mq-tin" type="radio" name="mq-t" id="mq-t-manage">

    <nav class="mq-tabs">
      {% comment %} The tab that opens always leads — an active tab sitting in second place reads
      as a mis-click. consoleFirst already implies Permissions.LogConsole. {% endcomment %}
      {% if consoleFirst %}
      <label class="mq-tab" for="mq-t-console"><i class="fa-solid fa-terminal"></i><span>{% t 'ServiceLayout.Console', 'Console' %}</span></label>
      <label class="mq-tab" for="mq-t-overview"><i class="fa-solid fa-circle-info"></i><span>{% t 'Docker.TabOvr', 'Overview' %}</span></label>
      {% else %}
      <label class="mq-tab" for="mq-t-overview"><i class="fa-solid fa-circle-info"></i><span>{% t 'Docker.TabOvr', 'Overview' %}</span></label>
      {% if Permissions.LogConsole %}<label class="mq-tab" for="mq-t-console"><i class="fa-solid fa-terminal"></i><span>{% t 'ServiceLayout.Console', 'Console' %}</span></label>{% endif %}
      {% endif %}
      {% if Permissions.Console %}<label class="mq-tab" for="mq-t-exec"><i class="fa-solid fa-keyboard"></i><span>{% t 'Service.Exec', 'Terminal' %}</span></label>{% endif %}
      <label class="mq-tab" for="mq-t-connect"><i class="fa-solid fa-plug"></i><span>{% t 'ServiceHome.Connect', 'Connect' %}</span></label>
      {% if Permissions.Logs %}<label class="mq-tab" for="mq-t-logs"><i class="fa-solid fa-file-lines"></i><span>{% t 'Service.Logs', 'Logs' %}</span></label>{% endif %}
      {% if Permissions.ServiceActivity %}<label class="mq-tab" for="mq-t-activity"><i class="fa-solid fa-clock-rotate-left"></i><span>{% t 'SvcLayout.Activity', 'Activity' %}</span></label>{% endif %}
      <label class="mq-tab" for="mq-t-manage"><i class="fa-solid fa-sliders"></i><span>{% t 'Global.Manage', 'Manage' %}</span></label>
    </nav>

    <div class="mq-stage">
      {% if Permissions.LogConsole %}
      <div class="mq-pane mq-pane--console">{% component "docker-logs-terminal" %}</div>
      {% endif %}

      <div class="mq-pane mq-pane--overview">{% component "service-details" %}</div>

      {% if Permissions.Console %}
      <div class="mq-pane mq-pane--exec">{% component "docker-exec-terminal" %}</div>
      {% endif %}

      <div class="mq-pane mq-pane--connect">
        <div class="mq-bay">
          <div class="mq-bay__row"><span class="mq-bay__k">{% t 'Db.Host', 'Host' %}</span><span class="mq-bay__v">{% component "service-host-address" %}</span></div>
        </div>
        {% if Service.Ports.size > 0 %}
        <p class="mq-sub">Published ports</p>
        <div class="mq-ports">
          {% for p in Service.Ports %}
          <div class="mq-port" data-part="item" data-kind="port">
            <span class="mq-port__n">{{ p.Port }}</span>
            <span class="mq-port__k">{{ p.Name }}</span>
            {% if p.Description and p.Description != '' %}<span class="mq-port__d">{{ p.Description }}</span>{% endif %}
            {% if p.Uri and p.Uri != '' %}<a class="mq-port__go" href="{{ p.Uri }}" target="_blank" rel="noopener" title="{% t 'Messages.Open', 'Open' %}"><i class="fa-solid fa-arrow-up-right-from-square"></i></a>{% endif %}
          </div>
          {% endfor %}
        </div>
        {% else %}
        <p class="mq-sub mq-sub--pad">Published ports</p>
        <p class="mq-none">This container publishes no ports.</p>
        {% endif %}
      </div>

      {% if Permissions.Logs %}
      <div class="mq-pane mq-pane--logs">
        <p class="mq-sub">{% t 'ServiceHome.RecentLogs', 'Recent Logs' %}<a href="{{ Service.Url }}/Logs">All logs</a></p>
        {% component "service-logs-list" %}
      </div>
      {% endif %}

      {% if Permissions.ServiceActivity %}
      <div class="mq-pane mq-pane--activity">
        <p class="mq-sub">{% t 'SvcHome.RctAct', 'Recent Activity' %}<a href="{{ Service.Url }}/Activity">All activity</a></p>
        {% component "service-activity-list" %}
      </div>
      {% endif %}

      <div class="mq-pane mq-pane--manage">{% component "service-advanced-actions" %}</div>
    </div>
  </section>
</div>

contents.css:
/* ============ VIRIDIAN · DockerService.Home surface ============
   The game surface's poster hero + workbench re-cut for a container: no slot bar, no network
   line, two docker terminals in the stage. Kept diffable against gamehome.css — docker-only
   rules are marked. */

/* The inherited docker header stands down on Home — the hero IS the header here.
   Sub-pages (no .mq present) keep it. */
body:has(.mq--dkr) .mlt-svh,
body:has(.mq--dkr) .mlt-svh__seam{display:none}

.mq{display:flex;flex-direction:column;gap:16px;font-family:var(--mq-ui)}

/* ============================== the marquee ============================== */
.mq-hero{position:relative;display:flex;align-items:center;gap:32px;isolation:isolate;
  padding:20px 26px 22px;border-radius:var(--mq-r);overflow:hidden;
  border:1px solid var(--mud-palette-lines-default);
  box-shadow:0 22px 60px rgba(0,0,0,.35);
  /* Left-weighted scrim so the poster text stays readable while the right half shows artwork. */
  background:
    linear-gradient(90deg,rgba(var(--mud-palette-surface-rgb),.97) 0 34%,rgba(var(--mud-palette-surface-rgb),.72) 58%,rgba(var(--mud-palette-surface-rgb),.42) 100%),
    linear-gradient(0deg,rgba(0,0,0,.45),transparent 60%);
  /* Docker blueprints CAN carry art (DockerServiceLayout renders .img-bg too) — amplify it
     locally like the game hero. No art = the gradients stand alone. */
  backdrop-filter:saturate(1.5) brightness(1.3) contrast(1.04);
  -webkit-backdrop-filter:saturate(1.5) brightness(1.3) contrast(1.04)}
/* Ember wash + the seam under it — both ride --tca-ember-now, so the hero warms and cools
   instead of switching colour. */
.mq-hero::before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;
  background:
    radial-gradient(110% 90% at 0% 100%,color-mix(in srgb,var(--tca-ember-now) 16%,transparent),transparent 60%),
    linear-gradient(90deg,color-mix(in srgb,var(--tca-ember-now) 7%,transparent),transparent 45%)}
.mq-hero::after{content:"";position:absolute;left:0;right:0;bottom:0;height:3px;
  background:linear-gradient(90deg,var(--tca-ember-now),
    color-mix(in srgb,var(--tca-ember-now) 45%,#fff) 40%,transparent 78%);
  opacity:calc(.85 * var(--tca-glow-now))}
html[data-tca-status="starting"] .mq-hero::after,
html[data-tca-status="stopping"] .mq-hero::after{
  background:linear-gradient(90deg,transparent,var(--mlt-ember-1),transparent);
  background-size:35% 100%;background-repeat:no-repeat;animation:mq-chase 1.6s linear infinite;opacity:1}
/* The artwork cools with everything else — driven off the lever, so it fades rather than switching. */
body:has(.mq) .mud-paper.img-bg{opacity:calc(.6 - var(--tca-cool) * .12);
  filter:grayscale(calc(var(--tca-cool) * .85)) brightness(calc(1 - var(--tca-cool) * .22))}

.mq-hero__body{flex:1;min-width:0;display:flex;flex-direction:column;align-items:flex-start;gap:11px}
.mq-kick{display:flex;align-items:center;gap:10px;margin:0;font-family:var(--mq-mono);
  font-size:.6rem;letter-spacing:.2em;text-transform:uppercase;opacity:.6}
.mq-kick i{width:3px;height:3px;border-radius:50%;background:currentColor;opacity:.7;flex:none}
.mq-head{display:flex;align-items:baseline;gap:20px;flex-wrap:wrap;min-width:0}
.mq-name{margin:0;font-family:var(--mq-poster);font-weight:400;line-height:.9;
  font-size:clamp(1.9rem,3.4vw,3rem);letter-spacing:.015em;
  text-shadow:0 4px 26px rgba(0,0,0,.55)}
.mq-state{display:flex;align-items:center;gap:10px;margin:0;font-size:.88rem;font-weight:500}
/* The word stays in plain text colour; only the orb carries hue, as in the inherited band. */
.mq-state b{font-weight:700;letter-spacing:.01em}
.mq-state__u{opacity:.55;font-size:.84rem}
.mq-state .tca-live-status-orb{width:11px;height:11px;border-radius:50%;flex:none;display:inline-block;
  background:rgba(var(--mud-palette-text-primary-rgb),.25)}
.mq-state .tca-live-status-orb[data-status="started"]{background:var(--mud-palette-success);
  box-shadow:0 0 14px color-mix(in srgb,var(--mud-palette-success) 80%,transparent)}
.mq-state .tca-live-status-orb[data-status="stopped"]{background:var(--mud-palette-error);
  box-shadow:0 0 10px color-mix(in srgb,var(--mud-palette-error) 55%,transparent)}
.mq-state .tca-live-status-orb[data-status="starting"],
.mq-state .tca-live-status-orb[data-status="stopping"]{background:var(--mud-palette-warning);
  box-shadow:0 0 14px color-mix(in srgb,var(--mud-palette-warning) 80%,transparent);
  animation:mq-blink 1.4s ease-in-out infinite}
/* Uptime is noise on a stopped container. Target the wrapper, NOT `span` — the status text and
   the orb are spans too, and hiding those collapses the whole line. */
html[data-tca-status="stopped"] .mq-state__u,
html[data-tca-status="unknown"] .mq-state__u{display:none}

/* ---- the call to action ---- */
.mq-cta{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:2px}
/* The ingot, same gradient as the brand chip and the inherited power buttons. */
.mq-join{display:inline-flex;align-items:center;gap:13px;height:52px;padding:0 26px 0 22px;
  border-radius:15px;text-decoration:none;color:var(--mlt-ink-on-ember);
  background:var(--mlt-molten);
  box-shadow:0 10px 30px rgba(var(--mlt-ember-rgb),.4),inset 0 1px 0 rgba(255,255,255,.5),inset 0 -2px 4px rgba(var(--mlt-ember-shade-rgb),.35);
  transition:transform .12s ease,box-shadow .2s ease,opacity .3s ease,filter .3s ease}
.mq-join:hover{transform:translateY(-2px);
  box-shadow:0 16px 40px rgba(var(--mlt-ember-rgb),.55),inset 0 1px 0 rgba(255,255,255,.5),inset 0 -2px 4px rgba(var(--mlt-ember-shade-rgb),.35)}
.mq-join:active{transform:translateY(0)}
.mq-join i{font-size:1.05rem}
.mq-join span{font-weight:700;font-size:1.02rem;letter-spacing:.02em}
.mq-join em{font-style:normal;font-family:var(--mq-mono);font-size:.72rem;letter-spacing:.04em;
  opacity:.72;padding-left:14px;border-left:1px solid rgba(0,0,0,.22)}
/* No launch URI: same slab, but it's a readout with a copy button, not a button. */
.mq-join--static{background:rgba(var(--mud-palette-text-primary-rgb),.06);color:var(--mud-palette-text-primary);
  border:1px solid var(--mud-palette-lines-default);box-shadow:none}
.mq-join--static:hover{transform:none;box-shadow:none}
.mq-join--static em{border-left-color:var(--mud-palette-lines-default);opacity:1}
/* The host atom in the slab: keep the address and its copy button on one tidy line. */
.mq-join--static em [data-part="value"]{display:inline-flex;align-items:center;gap:10px}
/* Opening a dead container is a dead end — say so instead of letting them try. */
html[data-tca-status="stopped"] .mq-join,
html[data-tca-status="unknown"] .mq-join{opacity:.32;filter:grayscale(1);pointer-events:none}
/* The static host readout stays copyable on a stopped container — it's a fact, not a launch. */
html[data-tca-status="stopped"] .mq-join--static,
html[data-tca-status="unknown"] .mq-join--static{opacity:.75;filter:none;pointer-events:auto}
/* Power keys re-expand here (the header sets the round-key base on game pages; docker sets the
   full pill directly). */
.mq-keys{display:flex;align-items:center;gap:9px}
.mq-keys [data-part="action"]{min-width:0;height:52px;padding:0 20px;border-radius:14px;
  border:1px solid var(--mud-palette-lines-default);background:rgba(var(--mud-palette-surface-rgb),.85);
  color:var(--mud-palette-text-primary);font-family:var(--mq-ui);font-weight:600;font-size:.76rem;
  letter-spacing:.1em;text-transform:uppercase;gap:9px;display:inline-flex;align-items:center;
  cursor:pointer;
  transition:transform .12s,border-color .15s,background .15s}
.mq-keys [data-part="action"]:hover{transform:translateY(-2px);background:rgba(var(--mud-palette-primary-rgb),.14)}
/* Uncooled by design — Start is what you want precisely when everything else has gone cold. */
.mq-keys [data-part="action"][data-kind="start"]{border-color:transparent;color:var(--mlt-ink-on-ember);
  background:var(--mlt-molten);
  box-shadow:0 8px 24px rgba(var(--mlt-ember-rgb),.4),inset 0 1px 0 rgba(255,255,255,.5)}
.mq-keys [data-part="action"][data-kind="kill"]{color:var(--mud-palette-error);
  border-color:color-mix(in srgb,var(--mud-palette-error) 50%,transparent)}

/* ---- vitals: vertical tubes, page-scoped --svc-* (a wrapper can't read a child's --pct) ---- */
.mq-vitals{display:flex;flex-direction:column;gap:11px;flex:none;padding:14px 18px;border-radius:var(--mq-r-sm);
  border:1px solid rgba(var(--mud-palette-text-primary-rgb),.14);
  background:rgba(var(--mud-palette-surface-rgb),.72);backdrop-filter:blur(9px);
  -webkit-backdrop-filter:blur(9px);transition:opacity .5s ease,filter .5s ease}
/* Stale numbers must look stale. Same drain the inherited rings use, off the same lever. */
.mq-vitals{filter:saturate(calc(1 - var(--tca-cool) * .8));opacity:calc(1 - var(--tca-cool) * .38)}
.mq-tubes{display:flex;gap:18px}
.mq-vital{display:flex;flex-direction:column;align-items:center;gap:6px;width:76px;text-align:center}
.mq-tube{position:relative;width:10px;height:62px;border-radius:6px;overflow:hidden;
  background:rgba(var(--mud-palette-text-primary-rgb),.11);
  box-shadow:inset 0 1px 3px rgba(0,0,0,.4)}
.mq-tube i{position:absolute;left:0;right:0;bottom:0;height:calc(var(--mq-p,0) * 1%);border-radius:7px;
  background:linear-gradient(180deg,var(--mq-tint),color-mix(in srgb,var(--mq-tint) 45%,transparent));
  box-shadow:0 0 12px var(--mq-tint)}
.mq-vital__n{font-family:var(--mq-poster);font-size:1.28rem;line-height:1;letter-spacing:.03em;
  margin-top:2px;white-space:nowrap}
.mq-vital__d{font-family:var(--mq-mono);font-size:.56rem;letter-spacing:.05em;opacity:.5;white-space:nowrap}
.mq-vital__k{font-family:var(--mq-mono);font-size:.53rem;letter-spacing:.18em;text-transform:uppercase;opacity:.45}
/* Continuous heat ramps — thresholds match the inherited rings, so both themes read the same
   load the same colour. */
.mq-vital--cpu{--mq-p:var(--svc-cpu,0);
  --mq-tint:color-mix(in srgb,var(--mud-palette-error) clamp(0%,calc((var(--svc-cpu,0) - 60) * 2.85%),100%),var(--mlt-ember-2))}
.mq-vital--mem{--mq-p:var(--svc-memory,0);
  --mq-tint:color-mix(in srgb,var(--mud-palette-error) clamp(0%,calc((var(--svc-memory,0) - 70) * 3.33%),100%),var(--mud-palette-secondary))}
.mq-vital--disk{--mq-p:var(--svc-disk,0);--mq-tint:var(--mud-palette-tertiary)}

/* ============================== the workbench ============================== */
.mq-work{display:flex;flex-direction:column;border-radius:var(--mq-r);overflow:hidden;
  border:1px solid var(--mud-palette-lines-default);
  background:rgba(var(--mud-palette-surface-rgb),.92);
  box-shadow:0 14px 40px rgba(0,0,0,.22)}
/* Off-screen, not display:none — the tabs stay keyboard-reachable. */
.mq-tin{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}

.mq-tabs{display:flex;align-items:center;gap:3px;padding:9px 11px;overflow-x:auto;
  border-bottom:1px solid var(--mud-palette-lines-default);
  background:linear-gradient(180deg,rgba(var(--mud-palette-text-primary-rgb),.04),transparent)}
.mq-tab{display:inline-flex;align-items:center;gap:9px;height:36px;padding:0 16px;flex:none;
  border-radius:11px;cursor:pointer;font-size:.79rem;font-weight:500;white-space:nowrap;
  color:var(--mud-palette-text-primary);opacity:.55;
  transition:opacity .15s,background .15s,color .15s}
.mq-tab i{font-size:.8rem}
.mq-tab:hover{opacity:1;background:rgba(var(--mud-palette-text-primary-rgb),.06)}

/* Selected tab. One rule per pairing — no :nth-child, because which tabs exist depends on the
   viewer's permissions. */
#mq-t-console:checked   ~ .mq-tabs label[for="mq-t-console"],
#mq-t-overview:checked  ~ .mq-tabs label[for="mq-t-overview"],
#mq-t-exec:checked      ~ .mq-tabs label[for="mq-t-exec"],
#mq-t-connect:checked   ~ .mq-tabs label[for="mq-t-connect"],
#mq-t-logs:checked      ~ .mq-tabs label[for="mq-t-logs"],
#mq-t-activity:checked  ~ .mq-tabs label[for="mq-t-activity"],
#mq-t-manage:checked    ~ .mq-tabs label[for="mq-t-manage"]{
  opacity:1;font-weight:600;color:var(--mud-palette-primary);
  background:rgba(var(--mud-palette-primary-rgb),.12);
  box-shadow:inset 0 -2px 0 var(--mud-palette-primary)}
/* Keyboard users get the same focus ring the labels can't inherit. */
#mq-t-console:focus-visible   ~ .mq-tabs label[for="mq-t-console"],
#mq-t-overview:focus-visible  ~ .mq-tabs label[for="mq-t-overview"],
#mq-t-exec:focus-visible      ~ .mq-tabs label[for="mq-t-exec"],
#mq-t-connect:focus-visible   ~ .mq-tabs label[for="mq-t-connect"],
#mq-t-logs:focus-visible      ~ .mq-tabs label[for="mq-t-logs"],
#mq-t-activity:focus-visible  ~ .mq-tabs label[for="mq-t-activity"],
#mq-t-manage:focus-visible    ~ .mq-tabs label[for="mq-t-manage"]{outline:2px solid var(--mud-palette-primary);outline-offset:-2px}

/* Stage: fixed height, panes stacked. visibility (not display) so both xterm terminals still
   measure themselves while hidden. */
.mq-stage{position:relative;height:540px;min-width:0}
.mq-pane{position:absolute;inset:0;visibility:hidden;min-width:0;overflow:auto}
.mq-pane--overview,.mq-pane--connect,.mq-pane--logs,.mq-pane--activity,.mq-pane--manage{padding:20px 22px}
#mq-t-console:checked  ~ .mq-stage .mq-pane--console,
#mq-t-overview:checked ~ .mq-stage .mq-pane--overview,
#mq-t-exec:checked     ~ .mq-stage .mq-pane--exec,
#mq-t-connect:checked  ~ .mq-stage .mq-pane--connect,
#mq-t-logs:checked     ~ .mq-stage .mq-pane--logs,
#mq-t-activity:checked ~ .mq-stage .mq-pane--activity,
#mq-t-manage:checked   ~ .mq-stage .mq-pane--manage{visibility:visible}
/* The terminals cool with the container; facts and actions stay just as relevant on a dead one. */
.mq-pane--console,.mq-pane--exec{overflow:hidden;
  filter:grayscale(var(--tca-cool)) contrast(calc(1 - var(--tca-cool) * .22));
  opacity:calc(1 - var(--tca-cool) * .45)}
/* Both docker terminals ship a .docker-terminal-wrapper with framing chrome and an inline 420px
   height — flatten the frame (the stage supplies it) and stretch to fill the pane. */
.mq-pane--console [data-tca-component="docker-logs-terminal"],
.mq-pane--exec [data-tca-component="docker-exec-terminal"]{height:100%!important;
  background:transparent;border:none;box-shadow:none}
/* An empty black rectangle reads as broken. Label it — pointer-events:none so scrollback stays
   usable. */
.mq-pane--console::after,.mq-pane--exec::after{content:"Offline — container is stopped";display:none;
  position:absolute;top:12px;right:16px;
  padding:5px 11px;border-radius:8px;pointer-events:none;
  font-family:var(--mq-mono);font-size:.56rem;letter-spacing:.18em;text-transform:uppercase;
  color:var(--mud-palette-error);background:color-mix(in srgb,var(--mud-palette-error) 12%,transparent);
  border:1px solid color-mix(in srgb,var(--mud-palette-error) 40%,transparent)}
html[data-tca-status="stopped"] .mq-pane--console::after,
html[data-tca-status="stopped"] .mq-pane--exec::after{display:block}

/* Dimmed with colour, not opacity — opacity compounds onto the link and buries it. */
.mq-sub{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin:0 0 14px;
  font-family:var(--mq-mono);font-size:.58rem;letter-spacing:.2em;text-transform:uppercase;
  color:rgba(var(--mud-palette-text-primary-rgb),.45)}
.mq-sub a{color:var(--mud-palette-primary);text-decoration:none}
.mq-sub a:hover{text-decoration:underline}
.mq-sub--pad{margin-top:18px}
.mq-none{margin:0;font-size:.84rem;opacity:.55}

/* ---- connect pane: the patch bay ---- */
.mq-bay{display:flex;flex-direction:column;border-radius:var(--mq-r-sm);overflow:hidden;
  border:1px solid var(--mud-palette-lines-default);margin-bottom:18px}
.mq-bay__row{display:flex;align-items:center;gap:18px;padding:13px 18px;
  border-bottom:1px solid rgba(var(--mud-palette-text-primary-rgb),.07)}
.mq-bay__row:last-child{border-bottom:none}
.mq-bay__k{width:74px;flex:none;font-family:var(--mq-mono);font-size:.56rem;letter-spacing:.2em;
  text-transform:uppercase;opacity:.45}
.mq-bay__v{font-family:var(--mq-mono);font-size:.92rem;letter-spacing:.03em;
  display:inline-flex;align-items:center;gap:8px;min-width:0}
/* The copy button lands wherever the address text ends — a shared min-width plus space-between
   parks every button in the same column. */
.mq-bay__v [data-part="value"]{display:inline-flex;align-items:center;gap:12px;
  justify-content:space-between;min-width:15em}
.mq-ports{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:10px}
.mq-port{position:relative;display:flex;flex-direction:column;gap:2px;padding:12px 14px;
  border-radius:var(--mq-r-sm);border:1px solid var(--mud-palette-lines-default);
  background:rgba(var(--mud-palette-text-primary-rgb),.03)}
.mq-port__n{font-family:var(--mq-poster);font-size:1.5rem;line-height:1;letter-spacing:.04em}
.mq-port__k{font-family:var(--mq-mono);font-size:.55rem;letter-spacing:.18em;text-transform:uppercase;opacity:.45}
.mq-port__d{font-size:.72rem;opacity:.6}
.mq-port__go{position:absolute;top:10px;right:11px;width:26px;height:26px;border-radius:8px;
  display:flex;align-items:center;justify-content:center;font-size:.66rem;text-decoration:none;
  color:var(--mud-palette-primary);border:1px solid color-mix(in srgb,var(--mud-palette-primary) 40%,transparent)}
.mq-port__go:hover{background:rgba(var(--mud-palette-primary-rgb),.14)}

/* ---- restyling INSIDE the kept tokens, data-part contract only ----
   Scoped under .mq-pane: beats the inherited global forge rules (0,3,0 vs 0,2,0), no !important.
   Not one .mud-* class below — the terminal wrapper above is a published class, not internals. */
.mq-pane [data-tca-component="service-details"]{border:1px solid var(--mud-palette-lines-default);
  border-radius:var(--mq-r-sm);overflow:hidden;background:transparent!important}
.mq-pane [data-tca-component="service-details"] [data-part="icon"]{display:none}
.mq-pane [data-tca-component="service-details"] [data-part="row"] td{padding:11px 18px;
  border-bottom:1px solid rgba(var(--mud-palette-text-primary-rgb),.06)}
.mq-pane [data-tca-component="service-details"] [data-part="row"]:last-child td{border-bottom:none}
.mq-pane [data-tca-component="service-details"] [data-part="row"] td:first-child{width:210px;
  background:rgba(var(--mud-palette-text-primary-rgb),.02)}
.mq-pane [data-tca-component="service-details"] [data-part="label"]{font-family:var(--mq-mono);
  font-size:.56rem;letter-spacing:.2em;text-transform:uppercase;opacity:.45}
.mq-pane [data-tca-component="service-details"] [data-part="value"]{font-family:var(--mq-ui);
  font-weight:600;font-size:.92rem;letter-spacing:0}
/* Ports are facts, not state — primary, never a status colour. */
.mq-pane [data-tca-component="service-details"] [data-part="item"][data-kind="port"]{
  font-family:var(--mq-mono)!important;font-size:.68rem;letter-spacing:.05em;border-radius:8px;
  border:1px solid color-mix(in srgb,var(--mud-palette-primary) 40%,transparent)!important;
  background:color-mix(in srgb,var(--mud-palette-primary) 9%,transparent)!important;
  color:var(--mud-palette-text-primary)!important}

/* Manage: cards, not a button list. data-kind is the only stable handle — which buttons render
   depends on the viewer's permissions. */
.mq-pane [data-tca-component="service-advanced-actions"]{background:transparent!important}
.mq-pane [data-tca-component="service-advanced-actions"] [data-part="list"]{display:grid;
  grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:11px}
.mq-pane [data-tca-component="service-advanced-actions"] [data-part="item"]{display:block}
.mq-pane [data-tca-component="service-advanced-actions"] [data-part="item"] td{display:block;padding:0;border:none}
.mq-pane [data-tca-component="service-advanced-actions"] [data-part="action"]{width:100%;height:64px;
  justify-content:flex-start;gap:12px;padding:0 16px;border-radius:14px;
  border:1px solid var(--mud-palette-lines-default);
  background:rgba(var(--mud-palette-text-primary-rgb),.03);
  font-family:var(--mq-ui);font-size:.78rem;font-weight:600;letter-spacing:.02em;text-transform:none;
  color:var(--mud-palette-text-primary);transition:transform .12s,background .15s,border-color .15s}
/* Hover rides the STATIONARY wrapper (a lifted button flees a bottom-edge cursor and vibrates),
   and washes in currentColor — a primary-orange film read as mud on warning/error buttons. */
.mq-pane [data-tca-component="service-advanced-actions"] [data-part="item"]:hover [data-part="action"]{transform:translateY(-2px);
  background:color-mix(in srgb,currentColor 10%,transparent)}
.mq-pane [data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="reinstall"],
.mq-pane [data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="repair"]{
  border-color:color-mix(in srgb,var(--mud-palette-warning) 45%,transparent);color:var(--mud-palette-warning)}
.mq-pane [data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="delete"]{
  border-color:color-mix(in srgb,var(--mud-palette-error) 55%,transparent);color:var(--mud-palette-error);
  background:color-mix(in srgb,var(--mud-palette-error) 7%,transparent)}

/* Logs + activity: flat rows in a tall stage. The activity list ships a 230px inline max-height
   for its own panel — it has a whole pane here. */
.mq-pane [data-tca-component="service-activity-list"] > div[style]{max-height:none!important}
/* The engine lists render NOTHING when empty (no [data-part="empty"]) and a bare pane reads
   as broken — supply the message. Flashes briefly during load; harmless. */
.mq-pane [data-tca-component="service-logs-list"]:not(:has([data-part="item"]))::after{
  content:"No log files yet.";font-size:.84rem;opacity:.55}
.mq-pane [data-tca-component="service-activity-list"]:not(:has([data-part="item"]))::after{
  content:"No recorded activity yet.";font-size:.84rem;opacity:.55}
.mq-pane [data-tca-component="service-logs-list"] [data-part="item"],
.mq-pane [data-tca-component="service-activity-list"] [data-part="item"]{border-radius:var(--mq-r-sm)}
.mq-pane [data-tca-component="service-logs-list"] [data-part="media"]{background:rgba(var(--mud-palette-primary-rgb),.14)!important;
  color:var(--mud-palette-primary)!important}
.mq-pane [data-tca-component="service-logs-list"] [data-part="value"]{font-family:var(--mq-mono);font-size:.8rem}
.mq-pane [data-tca-component="service-logs-list"] [data-part="meta"]{font-family:var(--mq-mono);font-size:.62rem;opacity:.45}
.mq-pane [data-tca-component="service-activity-list"] [data-part="value"]{background:transparent!important;
  box-shadow:none!important;border:none!important;padding:0!important;font-size:.8rem}

@keyframes mq-chase{from{background-position:-40% 0}to{background-position:140% 0}}
@keyframes mq-blink{0%,100%{opacity:1}50%{opacity:.25}}

/* ============================== responsive ============================== */
@media (max-width:1099.98px){
  .mq-hero{flex-direction:column;align-items:stretch;gap:16px}
  .mq-vitals{justify-content:space-around}
  .mq-tubes{justify-content:space-around}
}
@media (max-width:899.98px){
  .mq-hero{padding:18px 16px;border-radius:var(--mq-r-sm)}
  .mq-name{font-size:clamp(1.7rem,7vw,2.4rem)}
  .mq-join{width:100%;justify-content:center}
  .mq-join em{display:none}
  .mq-keys{width:100%}
  .mq-keys [data-part="action"]{flex:1;padding:0 10px}
  .mq-vitals{padding:12px 10px;gap:8px}
  .mq-vital{width:auto;flex:1}
  .mq-work{border-radius:var(--mq-r-sm)}
  .mq-tab{padding:0 12px}
  .mq-stage{height:460px}
  .mq-pane--overview,.mq-pane--connect,.mq-pane--logs,.mq-pane--activity,.mq-pane--manage{padding:14px}
  /* The desktop copy-button column (a shared 15em box, space-between) overflows narrow rows and
     clips the copy icon — below tablet width the button just follows the address. */
  .mq-bay__v [data-part="value"]{min-width:0;justify-content:flex-start}
}
/* Phones: icons only, so all seven switches fit without a scroll. */
@media (max-width:599.98px){
  .mq-tab span{display:none}
  .mq-tab{padding:0 14px}
  /* The fixed label column wastes a third of a phone row and squeezes the address into the edge —
     stack instead: label above, address + copy on their own full-width line. */
  .mq-bay__row{flex-direction:column;align-items:flex-start;gap:5px;padding:11px 14px}
  .mq-bay__k{width:auto}
  /* Same as the game home's phone block — see the long note there. Docker has TWO terminals
     (console = logs, exec); both keep the fixed 70vh absolute box so xterm is never resized
     underneath by another tab's content. */
  .mq-stage{height:auto;min-height:220px}
  .mq-pane{position:relative;inset:auto;display:none;overflow:visible}
  #mq-t-overview:checked ~ .mq-stage .mq-pane--overview,
  #mq-t-connect:checked  ~ .mq-stage .mq-pane--connect,
  #mq-t-logs:checked     ~ .mq-stage .mq-pane--logs,
  #mq-t-activity:checked ~ .mq-stage .mq-pane--activity,
  #mq-t-manage:checked   ~ .mq-stage .mq-pane--manage{display:block;visibility:visible}
  .mq-pane--console,.mq-pane--exec{position:absolute;top:0;left:0;right:0;height:70vh;
    display:block;overflow:hidden}
  #mq-t-console:checked ~ .mq-stage,
  #mq-t-exec:checked ~ .mq-stage{height:70vh}
}
@media (prefers-reduced-motion:reduce){
  .mq-hero::after,.mq-state .tca-live-status-orb{animation:none!important}
  .mq-join,.mq-keys [data-part="action"],.mq-tube i{transition:none}
}

/* ============ VIRIDIAN · GameService.Header surface ============
   Loads on every page of a service, so it also carries the shared power-key styling the hero
   reuses. Tokens come from the global row (base-extra.css). */

.mq-hd{display:flex;align-items:center;gap:22px;padding:12px 16px 13px;margin-bottom:10px;
  border-radius:var(--mq-r);border:1px solid var(--mud-palette-lines-default);
  background:linear-gradient(180deg,rgba(255,255,255,.05),transparent 55%),rgba(var(--mud-palette-surface-rgb),.93);
  box-shadow:0 10px 30px rgba(0,0,0,.22),inset 0 1px 0 rgba(255,255,255,.05);
  position:relative;overflow:hidden;isolation:isolate}

/* The bezel runs on the inherited ember lever, not a signal colour of its own — this strip sits
   under the topbar and beside the drawer on every service page, where a second hue reads as a
   different product. --tca-ember-now already carries state: lit when the service runs, ash when
   it's cold. The orb and status word keep the signal colours; those are information. */
.mq-hd::after{content:"";position:absolute;left:0;right:0;bottom:0;height:3px;
  background:linear-gradient(90deg,transparent,var(--tca-ember-now) 22%,
    color-mix(in srgb,var(--tca-ember-now) 70%,#fff) 50%,var(--tca-ember-now) 78%,transparent);
  opacity:calc(.35 + .6 * var(--tca-glow-now))}
/* Transitional states: the rail chases instead of sitting still. */
html[data-tca-status="starting"] .mq-hd::after,
html[data-tca-status="stopping"] .mq-hd::after{
  background:linear-gradient(90deg,transparent,var(--mlt-ember-1),transparent);
  background-size:38% 100%;background-repeat:no-repeat;opacity:.95;
  animation:mq-chase 1.6s linear infinite}

/* ---- identity ---- */
.mq-hd__id{display:flex;align-items:center;gap:13px;flex:none;min-width:0}
.mq-hd__cart{display:flex;align-items:center;justify-content:center;flex:none;width:42px;height:42px;
  border-radius:13px;background:rgba(var(--mud-palette-text-primary-rgb),.05);
  border:1px solid color-mix(in srgb,var(--tca-ember-now) 30%,var(--mud-palette-lines-default));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.06);position:relative}
/* Ember LED notched into the cartridge corner — glows hot, greys to ash when the forge is out. */
.mq-hd__cart::after{content:"";position:absolute;right:-3px;top:-3px;width:10px;height:10px;
  border-radius:50%;background:var(--tca-ember-now);border:2px solid var(--mud-palette-surface);
  box-shadow:0 0 10px color-mix(in srgb,var(--tca-ember-now) 85%,transparent)}
.mq-hd__cart .tca-service-icon{display:flex;align-items:center;line-height:0}
.mq-hd__stack{display:flex;flex-direction:column;gap:1px;min-width:0}
.mq-hd__name{font-family:var(--mq-poster);font-size:1.6rem;line-height:1;letter-spacing:.035em;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:34ch}
.mq-hd__meta{font-family:var(--mq-mono);font-size:.62rem;letter-spacing:.08em;opacity:.5;
  display:flex;align-items:center;gap:8px;white-space:nowrap}
.mq-hd__meta i{width:3px;height:3px;border-radius:50%;background:currentColor;opacity:.6;flex:none}

/* ---- flight strip: segmented readouts, values stay still and legible ---- */
.mq-hd__strip{display:flex;align-items:stretch;flex:1;min-width:0;overflow:hidden;
  border-radius:var(--mq-r-sm);border:1px solid var(--mud-palette-lines-default);
  background:rgba(var(--mud-palette-text-primary-rgb),.025);position:relative}
/* Motion WITHOUT moving the numbers: a highlight sweeps the strip while the server runs. */
.mq-hd__strip::after{content:"";position:absolute;inset:0;pointer-events:none;
  background:linear-gradient(100deg,transparent 35%,
    color-mix(in srgb,var(--mlt-ember-1) 16%,transparent) 50%,transparent 65%);
  background-size:220% 100%;animation:mq-sweep 6.5s linear infinite;opacity:var(--tca-glow-now)}
/* Even columns — a left-packed strip leaves a dead right half at desktop widths. */
.mq-cell{display:flex;flex:1 1 0;flex-direction:column;justify-content:center;gap:2px;padding:7px 16px;
  min-width:0;border-right:1px solid var(--mud-palette-lines-default)}
.mq-cell:last-child{border-right:none}
.mq-cell__k{font-family:var(--mq-mono);font-size:.53rem;letter-spacing:.18em;text-transform:uppercase;
  opacity:.42;white-space:nowrap}
.mq-cell__v{font-family:var(--mq-ui);font-weight:600;font-size:.9rem;line-height:1.15;
  font-variant-numeric:tabular-nums;display:flex;align-items:baseline;gap:5px;white-space:nowrap}
.mq-cell__v i{font-style:normal;font-size:.72rem;opacity:.45;font-weight:500}
/* Last-known numbers on a dead server must not read as live. */
html[data-tca-status="stopped"] .mq-cell:not(.mq-cell--state) .mq-cell__v{opacity:.4;filter:grayscale(1)}
/* Only the orb carries hue, as in the inherited band — the status word stays plain text. */
.mq-cell--state .mq-cell__v{gap:9px}
.mq-cell--state .tca-live-status-orb{width:9px;height:9px;border-radius:50%;flex:none;
  display:inline-block;align-self:center;background:rgba(var(--mud-palette-text-primary-rgb),.25)}
.mq-cell--state .tca-live-status-orb[data-status="started"]{background:var(--mud-palette-success);
  box-shadow:0 0 12px color-mix(in srgb,var(--mud-palette-success) 80%,transparent)}
.mq-cell--state .tca-live-status-orb[data-status="stopped"]{background:var(--mud-palette-error);
  box-shadow:0 0 9px color-mix(in srgb,var(--mud-palette-error) 55%,transparent)}
.mq-cell--state .tca-live-status-orb[data-status="starting"],
.mq-cell--state .tca-live-status-orb[data-status="stopping"]{background:var(--mud-palette-warning);
  box-shadow:0 0 12px color-mix(in srgb,var(--mud-palette-warning) 80%,transparent);
  animation:mq-blink 1.4s ease-in-out infinite}

/* ---- power keys: round hardware buttons, label suppressed (icon + tooltip carry it) ----
   data-part contract only, so a MudBlazor upgrade can't unstyle them. Shared with the hero,
   which re-expands them to labelled pills. */
.mq-hd__keys{display:flex;align-items:center;gap:8px;flex:none}
.mq-hd__keys [data-part="action"]{min-width:0;width:40px;height:40px;padding:0;border-radius:50%;
  border:1px solid var(--mud-palette-lines-default);
  background:rgba(var(--mud-palette-text-primary-rgb),.04);
  color:var(--mud-palette-text-primary);transition:transform .12s,border-color .15s,background .15s}
.mq-hd__keys [data-part="action"]:hover{transform:translateY(-1px);
  background:rgba(var(--mud-palette-primary-rgb),.12);border-color:var(--mud-palette-primary)}
.mq-hd__keys [data-part="action"] [data-part="label"]{display:none}
.mq-hd__keys [data-part="action"] [data-part="icon"]{margin:0}
/* Start wears the ingot gradient and is NOT cooled — the one control you want precisely when
   everything else has gone cold. */
.mq-hd__keys [data-part="action"][data-kind="start"]{border-color:transparent;color:var(--mlt-ink-on-ember);
  background:var(--mlt-molten);
  box-shadow:0 3px 12px rgba(var(--mlt-ember-rgb),.4),inset 0 1px 0 rgba(255,255,255,.45)}
.mq-hd__keys [data-part="action"][data-kind="kill"]{border-color:color-mix(in srgb,var(--mud-palette-error) 55%,transparent);
  color:var(--mud-palette-error)}

/* The home surface owns the identity there — see the file header. */
body:has(.mq) .mq-hd{display:none}

@keyframes mq-chase{from{background-position:-40% 0}to{background-position:140% 0}}
@keyframes mq-sweep{from{background-position:120% 0}to{background-position:-120% 0}}
@keyframes mq-blink{0%,100%{opacity:1}50%{opacity:.25}}

@media (max-width:1279.98px){
  .mq-cell--wide:nth-of-type(n+4){display:none}   /* keep state/uptime/players, drop the rest */
  .mq-hd__name{font-size:1.4rem;max-width:22ch}
}
@media (max-width:899.98px){
  .mq-hd{gap:12px;padding:10px 12px 11px}
  .mq-hd__strip{display:none}
  .mq-hd__id{flex:1}
  .mq-hd__keys [data-part="action"]{width:36px;height:36px}
}
@media (prefers-reduced-motion:reduce){
  .mq-hd__strip::after,.mq-hd::after,.mq-cell--state .tca-live-status-orb{animation:none!important}
}

contents.content:
{% comment %} MARQUEE game home — "front of house". A poster hero over the blueprint art with a
real JOIN action, a live slot bar and vertical vitals, then ONE workbench instead of a grid of
panels. The header surface stands down here — the hero IS the header. {% endcomment %}

{% comment %} First port carrying a click-to-connect URI. Plain loop, not map|compact, so it
can't depend on filter availability. Liquid trap: '' is TRUTHY (only nil/false are falsy), so
presence is compared against '' explicitly. {% endcomment %}
{% assign joinUri = '' %}
{% for p in Service.Ports %}{% if p.Uri and p.Uri != '' and joinUri == '' %}{% assign joinUri = p.Uri %}{% endif %}{% endfor %}
{% assign addr = Service.HostnameOrIp %}
{% if Service.GamePort %}{% assign addr = addr | append: ':' | append: Service.GamePort %}{% endif %}

<div class="mq">
  <div class="mq-alert">{% component "game-status-alert" %}</div>

  <!-- ============================ the marquee ============================ -->
  <section class="mq-hero">
    <div class="mq-hero__body">
      <p class="mq-kick">
        <span>{{ Service.BlueprintName }}</span><i></i><span>{{ addr }}</span>
        {% if Service.VirtualServerName %}<i></i><span>{{ Service.VirtualServerName }}</span>{% endif %}
      </p>

      {% comment %} Name and state share a line — the hero has to stay short enough that the
      workbench is on screen without scrolling. {% endcomment %}
      <div class="mq-head">
        <h1 class="mq-name">{% component "live-name" %}</h1>
        <p class="mq-state">
          {% component "live-status-orb" %}
          <b>{% component "live-status" %}</b>
          <span class="mq-state__u">for {% component "live-uptime" %}</span>
        </p>
      </div>

      <div class="mq-cta">
        {% comment %} CTA precedence: blueprint Connect URL → first port with a URI → copyable
        address. Started-only clickability is CSS off data-tca-status (live); Liquid here is
        only a render-time snapshot. {% endcomment %}
        {% if Service.ConnectUrl and Service.ConnectUrl != '' %}
        <a class="mq-join" href="{{ Service.ConnectUrl }}">
          <i class="fa-solid fa-plug"></i><span>{% t 'ServiceHome.Connect', 'Connect' %}</span><em>{{ addr }}</em>
        </a>
        {% elsif joinUri != '' %}
        <a class="mq-join" href="{{ joinUri }}">
          <i class="fa-solid fa-play"></i><span>Join server</span><em>{{ addr }}</em>
        </a>
        {% else %}
        {% comment %} No launch URI on this blueprint — offer the address to copy instead. {% endcomment %}
        <div class="mq-join mq-join--static">
          <i class="fa-solid fa-plug"></i><span>{% t 'ServiceHome.Connect', 'Connect' %}</span><em>{% component "game-connection-address" %}</em>
        </div>
        {% endif %}
        {% if Permissions.Control %}
        <div class="mq-keys">
          {% component "power-start" %}
          {% component "power-restart" %}
          {% component "power-stop" %}
          {% component "power-kill" %}
        </div>
        {% endif %}
      </div>

      {% if Permissions.PlayerStats %}
      <div class="mq-slots">
        <div class="mq-slots__track"><span class="mq-slots__fill"></span></div>
        <p class="mq-slots__cap">
          <b>{% component "live-players" %}</b>
          <span>of {% component "live-players-max" %} slots filled</span>
        </p>
      </div>
      {% endif %}
    </div>

    {% if Permissions.LiveStats %}
    <aside class="mq-vitals">
      <div class="mq-tubes">
      {% if Permissions.CpuStats %}
      <div class="mq-vital mq-vital--cpu">
        <span class="mq-tube"><i></i></span>
        <span class="mq-vital__n">{% component "live-cpu" %}</span>
        <span class="mq-vital__k">{% t 'ServiceHome.CPU', 'CPU' %}</span>
      </div>
      {% endif %}
      {% if Permissions.MemoryStats %}
      <div class="mq-vital mq-vital--mem">
        <span class="mq-tube"><i></i></span>
        <span class="mq-vital__n">{% component "live-memory" %}</span>
        <span class="mq-vital__d">of {% component "live-memory-limit" %}</span>
        <span class="mq-vital__k">{% t 'Global.Memory', 'Memory' %}</span>
      </div>
      {% endif %}
      <div class="mq-vital mq-vital--disk">
        <span class="mq-tube"><i></i></span>
        <span class="mq-vital__n">{% component "live-disk" %}</span>
        {% comment %} A disk quota is optional: no quota, no denominator and no --svc-disk sweep. {% endcomment %}
        {% if Service.DiskSpace %}<span class="mq-vital__d">of {% component "live-disk-limit" %}</span>{% endif %}
        <span class="mq-vital__k">{% t 'ServiceHome.Disk', 'DISK' %}</span>
      </div>
      </div>
      {% comment %} Network has no denominator, so no tube — it gets its own line under the gauges
      rather than a column that would break the tube baseline. {% endcomment %}
      {% if Permissions.NetworkStats %}
      <div class="mq-net">
        <span class="mq-net__k">Net</span>
        <span class="mq-net__v"><i class="fa-solid fa-arrow-up-long"></i>{% component "live-network-up" %}</span>
        <span class="mq-net__v"><i class="fa-solid fa-arrow-down-long"></i>{% component "live-network-down" %}</span>
      </div>
      {% endif %}
    </aside>
    {% endif %}
  </section>

  <!-- ============================ the workbench ============================ -->
  <section class="mq-work">
    {% comment %} Which tab opens is a load-time decision, so it belongs in Liquid: running means
    you came for the console, stopped means you came to fix or read. {% endcomment %}
    {% assign consoleFirst = false %}
    {% if Permissions.Console and Service.Status == 'Started' %}{% assign consoleFirst = true %}{% endif %}
    {% if Permissions.Console %}<input class="mq-tin" type="radio" name="mq-t" id="mq-t-console"{% if consoleFirst %} checked{% endif %}>{% endif %}
    <input class="mq-tin" type="radio" name="mq-t" id="mq-t-overview"{% unless consoleFirst %} checked{% endunless %}>
    <input class="mq-tin" type="radio" name="mq-t" id="mq-t-connect">
    {% if Permissions.Logs %}<input class="mq-tin" type="radio" name="mq-t" id="mq-t-logs">{% endif %}
    {% if Permissions.ServiceActivity %}<input class="mq-tin" type="radio" name="mq-t" id="mq-t-activity">{% endif %}
    <input class="mq-tin" type="radio" name="mq-t" id="mq-t-manage">

    {% comment %} A horizontal switcher, NOT a rail: the app's nav drawer is already a vertical menu
    on the left, and a second one beside it is both cramped and duplicated. {% endcomment %}
    <nav class="mq-tabs">
      {% comment %} The tab that opens always leads — an active tab sitting in second place reads as
      a mis-click. consoleFirst already implies Permissions.Console. {% endcomment %}
      {% if consoleFirst %}
      <label class="mq-tab" for="mq-t-console"><i class="fa-solid fa-terminal"></i><span>{% t 'ServiceLayout.Console', 'Console' %}</span></label>
      <label class="mq-tab" for="mq-t-overview"><i class="fa-solid fa-circle-info"></i><span>{% t 'Docker.TabOvr', 'Overview' %}</span></label>
      {% else %}
      <label class="mq-tab" for="mq-t-overview"><i class="fa-solid fa-circle-info"></i><span>{% t 'Docker.TabOvr', 'Overview' %}</span></label>
      {% if Permissions.Console %}<label class="mq-tab" for="mq-t-console"><i class="fa-solid fa-terminal"></i><span>{% t 'ServiceLayout.Console', 'Console' %}</span></label>{% endif %}
      {% endif %}
      <label class="mq-tab" for="mq-t-connect"><i class="fa-solid fa-plug"></i><span>{% t 'ServiceHome.Connect', 'Connect' %}</span></label>
      {% if Permissions.Logs %}<label class="mq-tab" for="mq-t-logs"><i class="fa-solid fa-file-lines"></i><span>{% t 'Service.Logs', 'Logs' %}</span></label>{% endif %}
      {% if Permissions.ServiceActivity %}<label class="mq-tab" for="mq-t-activity"><i class="fa-solid fa-clock-rotate-left"></i><span>{% t 'SvcLayout.Activity', 'Activity' %}</span></label>{% endif %}
      <label class="mq-tab" for="mq-t-manage"><i class="fa-solid fa-sliders"></i><span>{% t 'Global.Manage', 'Manage' %}</span></label>
    </nav>

    <div class="mq-stage">
      {% if Permissions.Console %}
      <div class="mq-pane mq-pane--console">{% component "game-console" %}</div>
      {% endif %}

      <div class="mq-pane mq-pane--overview">{% component "service-details" %}</div>

      <div class="mq-pane mq-pane--connect">
        <div class="mq-bay">
          <div class="mq-bay__row"><span class="mq-bay__k">{% t 'Global.Game', 'Game' %}</span><span class="mq-bay__v">{% component "game-connection-address" %}</span></div>
          <div class="mq-bay__row"><span class="mq-bay__k">FTPS</span><span class="mq-bay__v">{% component "game-ftps-address" %}</span></div>
          {% comment %} game-sftp-address renders nothing without an SFTP port, so the row starts
          display:none and CSS reveals it via :has(). {% endcomment %}
          <div class="mq-bay__row mq-bay__row--opt"><span class="mq-bay__k">SFTP</span><span class="mq-bay__v">{% component "game-sftp-address" %}</span></div>
          <div class="mq-bay__row"><span class="mq-bay__k">RCON</span><span class="mq-bay__v">{% component "game-rcon-address" %}</span></div>
        </div>
        {% if Service.Ports.size > 0 %}
        <p class="mq-sub">Allocated ports</p>
        <div class="mq-ports">
          {% for p in Service.Ports %}
          <div class="mq-port" data-part="item" data-kind="port">
            <span class="mq-port__n">{{ p.Port }}</span>
            <span class="mq-port__k">{{ p.Name }}</span>
            {% if p.Description and p.Description != '' %}<span class="mq-port__d">{{ p.Description }}</span>{% endif %}
            {% if p.Uri and p.Uri != '' %}<a class="mq-port__go" href="{{ p.Uri }}" title="Launch"><i class="fa-solid fa-arrow-up-right-from-square"></i></a>{% endif %}
          </div>
          {% endfor %}
        </div>
        {% endif %}
      </div>

      {% if Permissions.Logs %}
      <div class="mq-pane mq-pane--logs">
        <p class="mq-sub">{% t 'ServiceHome.RecentLogs', 'Recent Logs' %}<a href="{{ Service.Url }}/Logs">All logs</a></p>
        {% component "service-logs-list" %}
      </div>
      {% endif %}

      {% if Permissions.ServiceActivity %}
      <div class="mq-pane mq-pane--activity">
        <p class="mq-sub">{% t 'SvcHome.RctAct', 'Recent Activity' %}<a href="{{ Service.Url }}/Activity">All activity</a></p>
        {% component "service-activity-list" %}
      </div>
      {% endif %}

      <div class="mq-pane mq-pane--manage">{% component "service-advanced-actions" %}</div>
    </div>
  </section>
</div>

contents.css:
/* ============ VIRIDIAN · GameService.Home surface ============
   Two objects only: a poster hero and a workbench. Live numbers come from the headless live-*
   tokens, state reactions from data-tca-status / --svc-* on <html>. No JavaScript. */

.mq{display:flex;flex-direction:column;gap:16px;font-family:var(--mq-ui)}
.mq-alert:empty{display:none}
.mq-alert .mud-alert{border-radius:var(--mq-r)}

/* ============================== the marquee ============================== */
.mq-hero{position:relative;display:flex;align-items:center;gap:32px;isolation:isolate;
  padding:20px 26px 22px;border-radius:var(--mq-r);overflow:hidden;
  border:1px solid var(--mud-palette-lines-default);
  box-shadow:0 22px 60px rgba(0,0,0,.35);
  /* Left-weighted scrim so the poster text stays readable while the right half shows artwork. */
  background:
    linear-gradient(90deg,rgba(var(--mud-palette-surface-rgb),.97) 0 34%,rgba(var(--mud-palette-surface-rgb),.72) 58%,rgba(var(--mud-palette-surface-rgb),.42) 100%),
    linear-gradient(0deg,rgba(0,0,0,.45),transparent 60%);
  /* Blueprint art already sits behind the page (.img-bg, z-index:-10) at low opacity — amplify
     it locally rather than ship a second copy. No art = the gradients stand alone. */
  backdrop-filter:saturate(1.5) brightness(1.3) contrast(1.04);
  -webkit-backdrop-filter:saturate(1.5) brightness(1.3) contrast(1.04)}
/* Ember wash + seam — the inherited band's two cues at hero scale. Both ride --tca-ember-now,
   so the hero warms and cools rather than switching colour. */
.mq-hero::before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;
  background:
    radial-gradient(110% 90% at 0% 100%,color-mix(in srgb,var(--tca-ember-now) 16%,transparent),transparent 60%),
    linear-gradient(90deg,color-mix(in srgb,var(--tca-ember-now) 7%,transparent),transparent 45%)}
.mq-hero::after{content:"";position:absolute;left:0;right:0;bottom:0;height:3px;
  background:linear-gradient(90deg,var(--tca-ember-now),
    color-mix(in srgb,var(--tca-ember-now) 45%,#fff) 40%,transparent 78%);
  opacity:calc(.85 * var(--tca-glow-now))}
html[data-tca-status="starting"] .mq-hero::after,
html[data-tca-status="stopping"] .mq-hero::after{
  background:linear-gradient(90deg,transparent,var(--mlt-ember-1),transparent);
  background-size:35% 100%;background-repeat:no-repeat;animation:mq-chase 1.6s linear infinite;opacity:1}
/* The artwork cools with everything else — driven off the lever, so it fades rather than switching. */
body:has(.mq) .mud-paper.img-bg{opacity:calc(.6 - var(--tca-cool) * .12);
  filter:grayscale(calc(var(--tca-cool) * .85)) brightness(calc(1 - var(--tca-cool) * .22))}

.mq-hero__body{flex:1;min-width:0;display:flex;flex-direction:column;align-items:flex-start;gap:11px}
.mq-kick{display:flex;align-items:center;gap:10px;margin:0;font-family:var(--mq-mono);
  font-size:.6rem;letter-spacing:.2em;text-transform:uppercase;opacity:.6}
.mq-kick i{width:3px;height:3px;border-radius:50%;background:currentColor;opacity:.7;flex:none}
.mq-head{display:flex;align-items:baseline;gap:20px;flex-wrap:wrap;min-width:0}
.mq-name{margin:0;font-family:var(--mq-poster);font-weight:400;line-height:.9;
  font-size:clamp(1.9rem,3.4vw,3rem);letter-spacing:.015em;
  text-shadow:0 4px 26px rgba(0,0,0,.55)}
.mq-state{display:flex;align-items:center;gap:10px;margin:0;font-size:.88rem;font-weight:500}
/* The word stays in plain text colour; only the orb carries hue, as in the inherited band. */
.mq-state b{font-weight:700;letter-spacing:.01em}
.mq-state__u{opacity:.55;font-size:.84rem}
.mq-state .tca-live-status-orb{width:11px;height:11px;border-radius:50%;flex:none;display:inline-block;
  background:rgba(var(--mud-palette-text-primary-rgb),.25)}
.mq-state .tca-live-status-orb[data-status="started"]{background:var(--mud-palette-success);
  box-shadow:0 0 14px color-mix(in srgb,var(--mud-palette-success) 80%,transparent)}
.mq-state .tca-live-status-orb[data-status="stopped"]{background:var(--mud-palette-error);
  box-shadow:0 0 10px color-mix(in srgb,var(--mud-palette-error) 55%,transparent)}
.mq-state .tca-live-status-orb[data-status="starting"],
.mq-state .tca-live-status-orb[data-status="stopping"]{background:var(--mud-palette-warning);
  box-shadow:0 0 14px color-mix(in srgb,var(--mud-palette-warning) 80%,transparent);
  animation:mq-blink 1.4s ease-in-out infinite}
/* Uptime is noise on a stopped server. Target the wrapper, NOT `span` — the status text and the
   orb are spans too, and hiding those collapses the whole line. */
html[data-tca-status="stopped"] .mq-state__u,
html[data-tca-status="unknown"] .mq-state__u{display:none}

/* ---- the call to action ---- */
.mq-cta{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:2px}
/* The ingot, same gradient as the brand chip and the inherited power buttons. */
.mq-join{display:inline-flex;align-items:center;gap:13px;height:52px;padding:0 26px 0 22px;
  border-radius:15px;text-decoration:none;color:var(--mlt-ink-on-ember);
  background:var(--mlt-molten);
  box-shadow:0 10px 30px rgba(var(--mlt-ember-rgb),.4),inset 0 1px 0 rgba(255,255,255,.5),inset 0 -2px 4px rgba(var(--mlt-ember-shade-rgb),.35);
  transition:transform .12s ease,box-shadow .2s ease,opacity .3s ease,filter .3s ease}
.mq-join:hover{transform:translateY(-2px);
  box-shadow:0 16px 40px rgba(var(--mlt-ember-rgb),.55),inset 0 1px 0 rgba(255,255,255,.5),inset 0 -2px 4px rgba(var(--mlt-ember-shade-rgb),.35)}
.mq-join:active{transform:translateY(0)}
.mq-join i{font-size:1.05rem}
.mq-join span{font-weight:700;font-size:1.02rem;letter-spacing:.02em}
.mq-join em{font-style:normal;font-family:var(--mq-mono);font-size:.72rem;letter-spacing:.04em;
  opacity:.72;padding-left:14px;border-left:1px solid rgba(0,0,0,.22)}
/* No launch URI: same slab, but it's a readout with a copy button, not a button. */
.mq-join--static{background:rgba(var(--mud-palette-text-primary-rgb),.06);color:var(--mud-palette-text-primary);
  border:1px solid var(--mud-palette-lines-default);box-shadow:none}
.mq-join--static:hover{transform:none;box-shadow:none}
.mq-join--static em{border-left-color:var(--mud-palette-lines-default);opacity:1}
/* Joining a dead server is a dead end — say so instead of letting them try. */
html[data-tca-status="stopped"] .mq-join,
html[data-tca-status="unknown"] .mq-join{opacity:.32;filter:grayscale(1);pointer-events:none}
/* Power keys re-expand here (the header sets the round-key base). */
.mq-keys{display:flex;align-items:center;gap:9px}
.mq-keys [data-part="action"]{min-width:0;height:52px;padding:0 20px;border-radius:14px;
  border:1px solid var(--mud-palette-lines-default);background:rgba(var(--mud-palette-surface-rgb),.85);
  color:var(--mud-palette-text-primary);font-family:var(--mq-ui);font-weight:600;font-size:.76rem;
  letter-spacing:.1em;text-transform:uppercase;gap:9px;
  transition:transform .12s,border-color .15s,background .15s}
.mq-keys [data-part="action"]:hover{transform:translateY(-2px);background:rgba(var(--mud-palette-primary-rgb),.14)}
/* Uncooled by design — Start is what you want precisely when everything else has gone cold. */
.mq-keys [data-part="action"][data-kind="start"]{border-color:transparent;color:var(--mlt-ink-on-ember);
  background:var(--mlt-molten);
  box-shadow:0 8px 24px rgba(var(--mlt-ember-rgb),.4),inset 0 1px 0 rgba(255,255,255,.5)}
.mq-keys [data-part="action"][data-kind="kill"]{color:var(--mud-palette-error);
  border-color:color-mix(in srgb,var(--mud-palette-error) 50%,transparent)}

/* ---- slot bar: segmented like a seat map, driven by --svc-players ---- */
.mq-slots{width:min(560px,100%);display:flex;flex-direction:column;gap:6px;margin-top:2px}
.mq-slots__track{position:relative;height:13px;border-radius:7px;overflow:hidden;
  background:rgba(var(--mud-palette-text-primary-rgb),.1);
  box-shadow:inset 0 1px 3px rgba(0,0,0,.35)}
/* Success green, the one hue the players gauge already carries — and it drains with the forge. */
.mq-slots__fill{position:absolute;inset:0 auto 0 0;width:calc(var(--svc-players,0) * 1%);
  border-radius:7px;
  background:linear-gradient(90deg,color-mix(in srgb,var(--mud-palette-success) 55%,transparent),var(--mud-palette-success));
  filter:saturate(calc(1 - var(--tca-cool) * .8));opacity:calc(1 - var(--tca-cool) * .5)}
/* The seats. A mask, not a background, so the fill colour stays one gradient. */
.mq-slots__track::after{content:"";position:absolute;inset:0;pointer-events:none;
  background:repeating-linear-gradient(90deg,transparent 0 9px,rgba(var(--mud-palette-surface-rgb),.9) 9px 11px)}
html[data-tca-status="stopped"] .mq-slots__fill,
html[data-tca-status="unknown"] .mq-slots__fill{width:0}
.mq-slots__cap{margin:0;display:flex;align-items:baseline;gap:8px;font-size:.8rem;opacity:.75}
.mq-slots__cap b{font-family:var(--mq-poster);font-size:1.5rem;line-height:1;letter-spacing:.03em;
  color:var(--mud-palette-success);opacity:1;filter:saturate(calc(1 - var(--tca-cool) * .8))}

/* ---- vitals: vertical tubes, page-scoped --svc-* (a wrapper can't read a child's --pct) ---- */
.mq-vitals{display:flex;flex-direction:column;gap:11px;flex:none;padding:14px 18px;border-radius:var(--mq-r-sm);
  border:1px solid rgba(var(--mud-palette-text-primary-rgb),.14);
  background:rgba(var(--mud-palette-surface-rgb),.72);backdrop-filter:blur(9px);
  -webkit-backdrop-filter:blur(9px);transition:opacity .5s ease,filter .5s ease}
/* Stale numbers must look stale. Same drain the inherited rings use, off the same lever. */
.mq-vitals{filter:saturate(calc(1 - var(--tca-cool) * .8));opacity:calc(1 - var(--tca-cool) * .38)}
.mq-tubes{display:flex;gap:18px}
.mq-vital{display:flex;flex-direction:column;align-items:center;gap:6px;width:76px;text-align:center}
/* Network readout: bytes in/out, no percentage and therefore no tube. */
.mq-net{display:flex;align-items:center;justify-content:center;gap:16px;padding-top:10px;
  border-top:1px solid rgba(var(--mud-palette-text-primary-rgb),.1)}
.mq-net__k{font-family:var(--mq-mono);font-size:.53rem;letter-spacing:.18em;text-transform:uppercase;opacity:.45}
.mq-net__v{display:inline-flex;align-items:center;gap:6px;font-family:var(--mq-ui);font-weight:600;
  font-size:.82rem;font-variant-numeric:tabular-nums;white-space:nowrap}
.mq-net__v i{font-size:.66rem;opacity:.55}
.mq-tube{position:relative;width:10px;height:62px;border-radius:6px;overflow:hidden;
  background:rgba(var(--mud-palette-text-primary-rgb),.11);
  box-shadow:inset 0 1px 3px rgba(0,0,0,.4)}
.mq-tube i{position:absolute;left:0;right:0;bottom:0;height:calc(var(--mq-p,0) * 1%);border-radius:7px;
  background:linear-gradient(180deg,var(--mq-tint),color-mix(in srgb,var(--mq-tint) 45%,transparent));
  box-shadow:0 0 12px var(--mq-tint)}
.mq-vital__n{font-family:var(--mq-poster);font-size:1.28rem;line-height:1;letter-spacing:.03em;
  margin-top:2px;white-space:nowrap}
.mq-vital__d{font-family:var(--mq-mono);font-size:.56rem;letter-spacing:.05em;opacity:.5;white-space:nowrap}
.mq-vital__k{font-family:var(--mq-mono);font-size:.53rem;letter-spacing:.18em;text-transform:uppercase;opacity:.45}
/* Continuous heat ramps — the tube shades toward danger as load climbs, no JS, no tick.
   Thresholds match the inherited rings, so both themes read the same load the same colour:
   CPU ember→error above 60, memory secondary→error above 70, disk tertiary. */
.mq-vital--cpu{--mq-p:var(--svc-cpu,0);
  --mq-tint:color-mix(in srgb,var(--mud-palette-error) clamp(0%,calc((var(--svc-cpu,0) - 60) * 2.85%),100%),var(--mlt-ember-2))}
.mq-vital--mem{--mq-p:var(--svc-memory,0);
  --mq-tint:color-mix(in srgb,var(--mud-palette-error) clamp(0%,calc((var(--svc-memory,0) - 70) * 3.33%),100%),var(--mud-palette-secondary))}
.mq-vital--disk{--mq-p:var(--svc-disk,0);--mq-tint:var(--mud-palette-tertiary)}

/* ============================== the workbench ============================== */
.mq-work{display:flex;flex-direction:column;border-radius:var(--mq-r);overflow:hidden;
  border:1px solid var(--mud-palette-lines-default);
  background:rgba(var(--mud-palette-surface-rgb),.92);
  box-shadow:0 14px 40px rgba(0,0,0,.22)}
/* Off-screen, not display:none — the tabs stay keyboard-reachable. */
.mq-tin{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}

.mq-tabs{display:flex;align-items:center;gap:3px;padding:9px 11px;overflow-x:auto;
  border-bottom:1px solid var(--mud-palette-lines-default);
  background:linear-gradient(180deg,rgba(var(--mud-palette-text-primary-rgb),.04),transparent)}
.mq-tab{display:inline-flex;align-items:center;gap:9px;height:36px;padding:0 16px;flex:none;
  border-radius:11px;cursor:pointer;font-size:.79rem;font-weight:500;white-space:nowrap;
  color:var(--mud-palette-text-primary);opacity:.55;
  transition:opacity .15s,background .15s,color .15s}
.mq-tab i{font-size:.8rem}
.mq-tab:hover{opacity:1;background:rgba(var(--mud-palette-text-primary-rgb),.06)}

/* Selected tab. One rule per pairing — no :nth-child, because which tabs exist depends on the
   viewer's permissions. */
#mq-t-console:checked   ~ .mq-tabs label[for="mq-t-console"],
#mq-t-overview:checked  ~ .mq-tabs label[for="mq-t-overview"],
#mq-t-connect:checked   ~ .mq-tabs label[for="mq-t-connect"],
#mq-t-logs:checked      ~ .mq-tabs label[for="mq-t-logs"],
#mq-t-activity:checked  ~ .mq-tabs label[for="mq-t-activity"],
#mq-t-manage:checked    ~ .mq-tabs label[for="mq-t-manage"]{
  opacity:1;font-weight:600;color:var(--mud-palette-primary);
  background:rgba(var(--mud-palette-primary-rgb),.12);
  box-shadow:inset 0 -2px 0 var(--mud-palette-primary)}
/* Keyboard users get the same focus ring the labels can't inherit. */
#mq-t-console:focus-visible   ~ .mq-tabs label[for="mq-t-console"],
#mq-t-overview:focus-visible  ~ .mq-tabs label[for="mq-t-overview"],
#mq-t-connect:focus-visible   ~ .mq-tabs label[for="mq-t-connect"],
#mq-t-logs:focus-visible      ~ .mq-tabs label[for="mq-t-logs"],
#mq-t-activity:focus-visible  ~ .mq-tabs label[for="mq-t-activity"],
#mq-t-manage:focus-visible    ~ .mq-tabs label[for="mq-t-manage"]{outline:2px solid var(--mud-palette-primary);outline-offset:-2px}

/* Stage: fixed height, panes stacked. visibility (not display) so the console and any terminal
   still measure themselves while hidden. */
.mq-stage{position:relative;height:540px;min-width:0}
.mq-pane{position:absolute;inset:0;visibility:hidden;min-width:0;overflow:auto}
.mq-pane--overview,.mq-pane--connect,.mq-pane--logs,.mq-pane--activity,.mq-pane--manage{padding:20px 22px}
#mq-t-console:checked  ~ .mq-stage .mq-pane--console,
#mq-t-overview:checked ~ .mq-stage .mq-pane--overview,
#mq-t-connect:checked  ~ .mq-stage .mq-pane--connect,
#mq-t-logs:checked     ~ .mq-stage .mq-pane--logs,
#mq-t-activity:checked ~ .mq-stage .mq-pane--activity,
#mq-t-manage:checked   ~ .mq-stage .mq-pane--manage{visibility:visible}
/* The console cools with the service; facts and actions stay just as relevant on a dead server. */
.mq-pane--console{overflow:hidden;
  filter:grayscale(var(--tca-cool)) contrast(calc(1 - var(--tca-cool) * .22));
  opacity:calc(1 - var(--tca-cool) * .45)}
/* game-console is the one token with no data-part contract (it owns no element), so its chrome has
   to be reached by class. Flattening it lets the stage supply the frame. */
.mq-pane--console > .mud-paper{background:transparent!important;box-shadow:none!important;border:none!important}
/* An empty black rectangle reads as broken. Label it — pointer-events:none so scrollback stays usable. */
.mq-pane--console::after{content:"Offline — no live output";display:none;position:absolute;top:12px;right:16px;
  padding:5px 11px;border-radius:8px;pointer-events:none;
  font-family:var(--mq-mono);font-size:.56rem;letter-spacing:.18em;text-transform:uppercase;
  color:var(--mud-palette-error);background:color-mix(in srgb,var(--mud-palette-error) 12%,transparent);
  border:1px solid color-mix(in srgb,var(--mud-palette-error) 40%,transparent)}
html[data-tca-status="stopped"] .mq-pane--console::after{display:block}

/* Dimmed with colour, not opacity — opacity compounds onto the link and buried it. */
.mq-sub{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin:0 0 14px;
  font-family:var(--mq-mono);font-size:.58rem;letter-spacing:.2em;text-transform:uppercase;
  color:rgba(var(--mud-palette-text-primary-rgb),.45)}
.mq-sub a{color:var(--mud-palette-primary);text-decoration:none}
.mq-sub a:hover{text-decoration:underline}

/* ---- connect pane: a patch bay ---- */
.mq-bay{display:flex;flex-direction:column;border-radius:var(--mq-r-sm);overflow:hidden;
  border:1px solid var(--mud-palette-lines-default);margin-bottom:18px}
.mq-bay__row{display:flex;align-items:center;gap:18px;padding:13px 18px;
  border-bottom:1px solid rgba(var(--mud-palette-text-primary-rgb),.07)}
.mq-bay__row:last-child{border-bottom:none}
/* Optional endpoint: the atom renders nothing without an SFTP port, so the row starts hidden
   and :has() reveals it — no flash of an empty row while the entity loads. */
.mq-bay__row--opt{display:none}
.mq-bay__row--opt:has([data-part="value"]){display:flex}
.mq-bay__k{width:74px;flex:none;font-family:var(--mq-mono);font-size:.56rem;letter-spacing:.2em;
  text-transform:uppercase;opacity:.45}
.mq-bay__v{font-family:var(--mq-mono);font-size:.92rem;letter-spacing:.03em;
  display:inline-flex;align-items:center;gap:8px;min-width:0}
/* The copy button is a sibling of the address text node, so it lands wherever the address
   ends — ragged icons across different port lengths. Shared min-width + space-between
   parks them all in one column. */
.mq-bay__v [data-part="value"]{display:inline-flex;align-items:center;gap:12px;
  justify-content:space-between;min-width:15em}
.mq-ports{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:10px}
.mq-port{position:relative;display:flex;flex-direction:column;gap:2px;padding:12px 14px;
  border-radius:var(--mq-r-sm);border:1px solid var(--mud-palette-lines-default);
  background:rgba(var(--mud-palette-text-primary-rgb),.03)}
.mq-port__n{font-family:var(--mq-poster);font-size:1.5rem;line-height:1;letter-spacing:.04em}
.mq-port__k{font-family:var(--mq-mono);font-size:.55rem;letter-spacing:.18em;text-transform:uppercase;opacity:.45}
.mq-port__d{font-size:.72rem;opacity:.6}
.mq-port__go{position:absolute;top:10px;right:11px;width:26px;height:26px;border-radius:8px;
  display:flex;align-items:center;justify-content:center;font-size:.66rem;text-decoration:none;
  color:var(--mud-palette-primary);border:1px solid color-mix(in srgb,var(--mud-palette-primary) 40%,transparent)}
.mq-port__go:hover{background:rgba(var(--mud-palette-primary-rgb),.14)}

/* ---- restyling INSIDE the kept tokens, data-part contract only ----
   Scoped under .mq-pane: beats the inherited global forge rules (0,3,0 vs 0,2,0) without
   !important, and leaves the docker home on the inherited look. Not one .mud-* class below. */
.mq-pane [data-tca-component="service-details"]{border:1px solid var(--mud-palette-lines-default);
  border-radius:var(--mq-r-sm);overflow:hidden;background:transparent!important}
.mq-pane [data-tca-component="service-details"] [data-part="icon"]{display:none}
.mq-pane [data-tca-component="service-details"] [data-part="row"] td{padding:11px 18px;
  border-bottom:1px solid rgba(var(--mud-palette-text-primary-rgb),.06)}
.mq-pane [data-tca-component="service-details"] [data-part="row"]:last-child td{border-bottom:none}
.mq-pane [data-tca-component="service-details"] [data-part="row"] td:first-child{width:210px;
  background:rgba(var(--mud-palette-text-primary-rgb),.02)}
.mq-pane [data-tca-component="service-details"] [data-part="label"]{font-family:var(--mq-mono);
  font-size:.56rem;letter-spacing:.2em;text-transform:uppercase;opacity:.45}
.mq-pane [data-tca-component="service-details"] [data-part="value"]{font-family:var(--mq-ui);
  font-weight:600;font-size:.92rem;letter-spacing:0}
/* Ports are facts, not state — never the signal colour, or a stopped server paints them red */
.mq-pane [data-tca-component="service-details"] [data-part="item"][data-kind="port"]{
  font-family:var(--mq-mono)!important;font-size:.68rem;letter-spacing:.05em;border-radius:8px;
  border:1px solid color-mix(in srgb,var(--mud-palette-primary) 40%,transparent)!important;
  background:color-mix(in srgb,var(--mud-palette-primary) 9%,transparent)!important;
  color:var(--mud-palette-text-primary)!important}

/* Manage: cards, not a button list. data-kind is the only stable handle — which buttons render
   depends on the viewer's permissions. */
.mq-pane [data-tca-component="service-advanced-actions"]{background:transparent!important}
.mq-pane [data-tca-component="service-advanced-actions"] [data-part="list"]{display:grid;
  grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:11px}
.mq-pane [data-tca-component="service-advanced-actions"] [data-part="item"]{display:block}
.mq-pane [data-tca-component="service-advanced-actions"] [data-part="item"] td{display:block;padding:0;border:none}
.mq-pane [data-tca-component="service-advanced-actions"] [data-part="action"]{width:100%;height:64px;
  justify-content:flex-start;gap:12px;padding:0 16px;border-radius:14px;
  border:1px solid var(--mud-palette-lines-default);
  background:rgba(var(--mud-palette-text-primary-rgb),.03);
  font-family:var(--mq-ui);font-size:.78rem;font-weight:600;letter-spacing:.02em;text-transform:none;
  color:var(--mud-palette-text-primary);transition:transform .12s,background .15s,border-color .15s}
/* Hover rides the STATIONARY wrapper (a lifted button flees a bottom-edge cursor and vibrates),
   and washes in currentColor — a primary-orange film read as mud on warning/error buttons. */
.mq-pane [data-tca-component="service-advanced-actions"] [data-part="item"]:hover [data-part="action"]{transform:translateY(-2px);
  background:color-mix(in srgb,currentColor 10%,transparent)}
.mq-pane [data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="reinstall"],
.mq-pane [data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="repair"]{
  border-color:color-mix(in srgb,var(--mud-palette-warning) 45%,transparent);color:var(--mud-palette-warning)}
.mq-pane [data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="delete"]{
  border-color:color-mix(in srgb,var(--mud-palette-error) 55%,transparent);color:var(--mud-palette-error);
  background:color-mix(in srgb,var(--mud-palette-error) 7%,transparent)}

/* Logs + activity: flat rows in a tall stage. The activity list ships an inline 230px
   max-height for its own panel — here it has a whole pane. */
.mq-pane [data-tca-component="service-activity-list"] > div[style]{max-height:none!important}
/* The engine lists render NOTHING when empty (no [data-part="empty"]) and a bare pane reads
   as broken — supply the message. Flashes briefly during load; harmless. */
.mq-pane [data-tca-component="service-logs-list"]:not(:has([data-part="item"]))::after{
  content:"No log files yet.";font-size:.84rem;opacity:.55}
.mq-pane [data-tca-component="service-activity-list"]:not(:has([data-part="item"]))::after{
  content:"No recorded activity yet.";font-size:.84rem;opacity:.55}
.mq-pane [data-tca-component="service-logs-list"] [data-part="item"],
.mq-pane [data-tca-component="service-activity-list"] [data-part="item"]{border-radius:var(--mq-r-sm)}
.mq-pane [data-tca-component="service-logs-list"] [data-part="media"]{background:rgba(var(--mud-palette-primary-rgb),.14)!important;
  color:var(--mud-palette-primary)!important}
.mq-pane [data-tca-component="service-logs-list"] [data-part="value"]{font-family:var(--mq-mono);font-size:.8rem}
.mq-pane [data-tca-component="service-logs-list"] [data-part="meta"]{font-family:var(--mq-mono);font-size:.62rem;opacity:.45}
.mq-pane [data-tca-component="service-activity-list"] [data-part="value"]{background:transparent!important;
  box-shadow:none!important;border:none!important;padding:0!important;font-size:.8rem}

@keyframes mq-chase{from{background-position:-40% 0}to{background-position:140% 0}}
@keyframes mq-blink{0%,100%{opacity:1}50%{opacity:.25}}

/* ============================== responsive ============================== */
@media (max-width:1099.98px){
  .mq-hero{flex-direction:column;align-items:stretch;gap:16px}
  .mq-vitals{justify-content:space-around}
}
@media (max-width:899.98px){
  .mq-hero{padding:18px 16px;border-radius:var(--mq-r-sm)}
  .mq-name{font-size:clamp(1.7rem,7vw,2.4rem)}
  .mq-join{width:100%;justify-content:center}
  .mq-join em{display:none}
  .mq-keys{width:100%}
  .mq-keys [data-part="action"]{flex:1;padding:0 10px}
  .mq-vitals{padding:12px 10px;gap:8px}
  .mq-vital{width:auto;flex:1}
  .mq-work{border-radius:var(--mq-r-sm)}
  .mq-tab{padding:0 12px}
  .mq-stage{height:460px}
  .mq-pane--overview,.mq-pane--connect,.mq-pane--logs,.mq-pane--activity,.mq-pane--manage{padding:14px}
  /* The desktop copy-button column (a shared 15em box, space-between) overflows narrow rows and
     clips the copy icon — below tablet width the button just follows the address. */
  .mq-bay__v [data-part="value"]{min-width:0;justify-content:flex-start}
}
/* Phones: icons only, so all six switches fit without a scroll. */
@media (max-width:599.98px){
  .mq-tab span{display:none}
  .mq-tab{padding:0 14px}
  /* The fixed label column wastes a third of a phone row and squeezes the address into the edge —
     stack instead: label above, address + copy on their own full-width line. */
  .mq-bay__row{flex-direction:column;align-items:flex-start;gap:5px;padding:11px 14px}
  .mq-bay__k{width:auto}
  /* Same move for the COMPILED details table. base.css already stacks it on phones, but the
     210px rule above outranks it (extra .mq-pane class) — restate at this specificity or the
     ports keep stacking one per line. */
  .mq-pane [data-tca-component="service-details"] [data-part="row"] td{padding:0 16px;border-bottom:none}
  .mq-pane [data-tca-component="service-details"] [data-part="row"] td:first-child{
    width:auto;background:transparent;padding-top:9px}
  .mq-pane [data-tca-component="service-details"] [data-part="row"] td:last-child{padding-bottom:11px}

  /* Phones: the page scrolls, not a 460px box inside it (a nested scroller is a trap). Non-terminal
     panes rejoin the flow so the stage grows to fit; the console can't, since xterm renders 0 rows
     in a zero-height box — it keeps an absolute box at a fixed 70vh and the stage matches. */
  .mq-stage{height:auto;min-height:220px}
  .mq-pane{position:relative;inset:auto;display:none;overflow:visible}
  #mq-t-overview:checked ~ .mq-stage .mq-pane--overview,
  #mq-t-connect:checked  ~ .mq-stage .mq-pane--connect,
  #mq-t-logs:checked     ~ .mq-stage .mq-pane--logs,
  #mq-t-activity:checked ~ .mq-stage .mq-pane--activity,
  #mq-t-manage:checked   ~ .mq-stage .mq-pane--manage{display:block;visibility:visible}
  .mq-pane--console{position:absolute;top:0;left:0;right:0;height:70vh;display:block;overflow:hidden}
  #mq-t-console:checked ~ .mq-stage{height:70vh}
}
@media (prefers-reduced-motion:reduce){
  .mq-hero::after,.mq-state .tca-live-status-orb{animation:none!important}
  .mq-join,.mq-keys [data-part="action"],.mq-slots__fill,.mq-tube i{transition:none}
}

